114	    public static Date parse(Object value) {
115	        if (value == null) {
116	            return null;
117	        }
118	        if (value instanceof Date) {
119	            return (Date) value;
120	        }
121	        if (value instanceof Calendar) {
122	            return ((Calendar) value).getTime();
123	        }
124	        if (value.getClass() == Instant.class) {
125	            return Date.from((Instant) value);
126	        }
127	        if (value instanceof TemporalAccessor) {
128	            return Date.from(Instant.from((TemporalAccessor) value));
129	        }
130	        if (value instanceof Number) {
131	            return new Date(((Number) value).longValue());
132	        }
133	        if (value instanceof CharSequence) {
134	            return parse(value.toString());
135	        }
136	        throw new IllegalArgumentException("Can not cast to Date, value : '" + value + "'");
137	    }
