28	/**
29	 * LeastActiveLoadBalance
30	 * <p>
31	 * Filter the number of invokers with the least number of active calls and count the weights and quantities of these invokers.
32	 * If there is only one invoker, use the invoker directly;
33	 * If there are multiple invokers and the weights are not the same, then random according to the total weight;
34	 * If there are multiple invokers and the same weight, then randomly called.
35	 */
36	public class LeastActiveLoadBalance extends AbstractLoadBalance {
37	
38	    public static final String NAME = "leastactive";
39	
40	    @Override
41	    protected <T> Invoker<T> doSelect(List<Invoker<T>> invokers, URL url, Invocation invocation) {
42	        // Number of invokers
43	        int length = invokers.size();
44	        // The least active value of all invokers
45	        int leastActive = -1;
46	        // The number of invokers having the same least active value (leastActive)
47	        int leastCount = 0;
48	        // The index of invokers having the same least active value (leastActive)
49	        int[] leastIndexes = new int[length];
50	        // the weight of every invokers
51	        int[] weights = new int[length];
52	        // The sum of the warmup weights of all the least active invokers
53	        int totalWeight = 0;
54	        // The weight of the first least active invoker
55	        int firstWeight = 0;
56	        // Every least active invoker has the same weight value?
57	        boolean sameWeight = true;
58	
59	        // Filter out all the least active invokers
60	        for (int i = 0; i < length; i++) {
61	            Invoker<T> invoker = invokers.get(i);
62	            // Get the active number of the invoker
63	            int active = RpcStatus.getStatus(invoker.getUrl(), RpcUtils.getMethodName(invocation))
64	                    .getActive();
65	            // Get the weight of the invoker's configuration. The default value is 100.
66	            int afterWarmup = getWeight(invoker, invocation);
67	            // save for later use
68	            weights[i] = afterWarmup;
69	            // If it is the first invoker or the active number of the invoker is less than the current least active
70	            // number
71	            if (leastActive == -1 || active < leastActive) {
72	                // Reset the active number of the current invoker to the least active number
73	                leastActive = active;
74	                // Reset the number of least active invokers
75	                leastCount = 1;
76	                // Put the first least active invoker first in leastIndexes
77	                leastIndexes[0] = i;
78	                // Reset totalWeight
79	                totalWeight = afterWarmup;
80	                // Record the weight the first least active invoker
81	                firstWeight = afterWarmup;
82	                // Each invoke has the same weight (only one invoker here)
83	                sameWeight = true;
84	                // If current invoker's active value equals with leaseActive, then accumulating.
85	            } else if (active == leastActive) {
86	                // Record the index of the least active invoker in leastIndexes order
87	                leastIndexes[leastCount++] = i;
88	                // Accumulate the total weight of the least active invoker
89	                totalWeight += afterWarmup;
90	                // If every invoker has the same weight?
91	                if (sameWeight && afterWarmup != firstWeight) {
92	                    sameWeight = false;
93	                }
94	            }
95	        }
96	        // Choose an invoker from all the least active invokers
97	        if (leastCount == 1) {
98	            // If we got exactly one invoker having the least active value, return this invoker directly.
99	            return invokers.get(leastIndexes[0]);
100	        }
101	        if (!sameWeight && totalWeight > 0) {
102	            // If (not every invoker has the same weight & at least one invoker's weight>0), select randomly based on
103	            // totalWeight.
104	            int offsetWeight = ThreadLocalRandom.current().nextInt(totalWeight);
105	            // Return a invoker based on the random value.
106	            for (int i = 0; i < leastCount; i++) {
107	                int leastIndex = leastIndexes[i];
108	                offsetWeight -= weights[leastIndex];
109	                if (offsetWeight < 0) {
110	                    return invokers.get(leastIndex);
111	                }
112	            }
113	        }
114	        // If all invokers have the same weight value or totalWeight=0, return evenly.
115	        return invokers.get(leastIndexes[ThreadLocalRandom.current().nextInt(leastCount)]);
116	    }
117	}
118

100	            return getSucceededAverageElapsed() * active;
101	        }
102	    }
