104	    @Override
105	    protected <T> Invoker<T> doSelect(List<Invoker<T>> invokers, URL url, Invocation invocation) {
106	        // Number of invokers
107	        int length = invokers.size();
108	        // Estimated shortest response time of all invokers
109	        long shortestResponse = Long.MAX_VALUE;
110	        // The number of invokers having the same estimated shortest response time
111	        int shortestCount = 0;
112	        // The index of invokers having the same estimated shortest response time
113	        int[] shortestIndexes = new int[length];
114	        // the weight of every invokers
115	        int[] weights = new int[length];
116	        // The sum of the warmup weights of all the shortest response  invokers
117	        int totalWeight = 0;
118	        // The weight of the first shortest response invokers
119	        int firstWeight = 0;
120	        // Every shortest response invoker has the same weight value?
121	        boolean sameWeight = true;
122	
123	        // Filter out all the shortest response invokers
124	        for (int i = 0; i < length; i++) {
125	            Invoker<T> invoker = invokers.get(i);
126	            RpcStatus rpcStatus = RpcStatus.getStatus(invoker.getUrl(), RpcUtils.getMethodName(invocation));
127	            SlideWindowData slideWindowData =
128	                    ConcurrentHashMapUtils.computeIfAbsent(methodMap, rpcStatus, SlideWindowData::new);
129	
130	            // Calculate the estimated response time from the product of active connections and succeeded average
131	            // elapsed time.
132	            long estimateResponse = slideWindowData.getEstimateResponse();
133	            int afterWarmup = getWeight(invoker, invocation);
134	            weights[i] = afterWarmup;
135	            // Same as LeastActiveLoadBalance
136	            if (estimateResponse < shortestResponse) {
137	                shortestResponse = estimateResponse;
138	                shortestCount = 1;
139	                shortestIndexes[0] = i;
140	                totalWeight = afterWarmup;
141	                firstWeight = afterWarmup;
142	                sameWeight = true;
143	            } else if (estimateResponse == shortestResponse) {
144	                shortestIndexes[shortestCount++] = i;
145	                totalWeight += afterWarmup;
146	                if (sameWeight && i > 0 && afterWarmup != firstWeight) {
147	                    sameWeight = false;
148	                }
149	            }
150	        }
151	
152	        if (System.currentTimeMillis() - lastUpdateTime > slidePeriod
153	                && onResetSlideWindow.compareAndSet(false, true)) {
154	            // reset slideWindowData in async way
155	            executorService.execute(() -> {
156	                methodMap.values().forEach(SlideWindowData::reset);
157	                lastUpdateTime = System.currentTimeMillis();
158	                onResetSlideWindow.set(false);
159	            });
160	        }
161	
162	        if (shortestCount == 1) {
163	            return invokers.get(shortestIndexes[0]);
164	        }
165	        if (!sameWeight && totalWeight > 0) {
166	            int offsetWeight = ThreadLocalRandom.current().nextInt(totalWeight);
167	            for (int i = 0; i < shortestCount; i++) {
168	                int shortestIndex = shortestIndexes[i];
169	                offsetWeight -= weights[shortestIndex];
170	                if (offsetWeight < 0) {
171	                    return invokers.get(shortestIndex);
172	                }
173	            }
174	        }
175	        return invokers.get(shortestIndexes[ThreadLocalRandom.current().nextInt(shortestCount)]);
176	    }
177	}
