28	
29	import static org.apache.dubbo.common.constants.CommonConstants.TIMESTAMP_KEY;
30	import static org.apache.dubbo.common.constants.RegistryConstants.REGISTRY_SERVICE_REFERENCE_PATH;
31	import static org.apache.dubbo.rpc.cluster.Constants.DEFAULT_WARMUP;
32	import static org.apache.dubbo.rpc.cluster.Constants.DEFAULT_WEIGHT;
33	import static org.apache.dubbo.rpc.cluster.Constants.WARMUP_KEY;
34	import static org.apache.dubbo.rpc.cluster.Constants.WEIGHT_KEY;
35	
36	public abstract class AbstractLoadBalance implements LoadBalance {
37	    /**
38	     * Calculate the weight according to the uptime proportion of warmup time
39	     * the new weight will be within 1(inclusive) to weight(inclusive)
40	     *
41	     * @param uptime the uptime in milliseconds
42	     * @param warmup the warmup time in milliseconds
43	     * @param weight the weight of an invoker
44	     * @return weight which takes warmup into account
45	     */
46	    static int calculateWarmupWeight(int uptime, int warmup, int weight) {
47	        int ww = (int) (uptime / ((float) warmup / weight));
48	        return ww < 1 ? 1 : (Math.min(ww, weight));
49	    }
50	
51	    @Override
52	    public <T> Invoker<T> select(List<Invoker<T>> invokers, URL url, Invocation invocation) {
53	        if (CollectionUtils.isEmpty(invokers)) {
54	            return null;
55	        }
56	        if (invokers.size() == 1) {
57	            return invokers.get(0);
58	        }
59	        return doSelect(invokers, url, invocation);
60	    }
61	
62	    protected abstract <T> Invoker<T> doSelect(List<Invoker<T>> invokers, URL url, Invocation invocation);
63	
64	    /**
65	     * Get the weight of the invoker's invocation which takes warmup time into account
66	     * if the uptime is within the warmup time, the weight will be reduce proportionally
67	     *
68	     * @param invoker    the invoker
69	     * @param invocation the invocation of this invoker
70	     * @return weight
71	     */
72	    protected int getWeight(Invoker<?> invoker, Invocation invocation) {
73	        int weight;
74	        URL url = invoker.getUrl();
75	        if (invoker instanceof ClusterInvoker) {
76	            url = ((ClusterInvoker<?>) invoker).getRegistryUrl();
77	        }
78	
79	        // Multiple registry scenario, load balance among multiple registries.
80	        if (REGISTRY_SERVICE_REFERENCE_PATH.equals(url.getServiceInterface())) {
81	            weight = url.getParameter(WEIGHT_KEY, DEFAULT_WEIGHT);
82	        } else {
83	            weight = url.getMethodParameter(RpcUtils.getMethodName(invocation), WEIGHT_KEY, DEFAULT_WEIGHT);
84	            if (weight > 0) {
85	                long timestamp = invoker.getUrl().getParameter(TIMESTAMP_KEY, 0L);
86	                if (timestamp > 0L) {
87	                    long uptime = System.currentTimeMillis() - timestamp;
88	                    if (uptime < 0) {
89	                        return 1;
90	                    }
91	                    int warmup = invoker.getUrl().getParameter(WARMUP_KEY, DEFAULT_WARMUP);
92	                    if (uptime > 0 && uptime < warmup) {
93	                        weight = calculateWarmupWeight((int) uptime, warmup, weight);
94	                    }
95	                }
96	            }
97	        }
98	        return Math.max(weight, 0);
99	    }
100	}
