import java.util.List;
import java.util.concurrent.ThreadLocalRandom;

import static org.apache.dubbo.common.constants.CommonConstants.TIMESTAMP_KEY;

protected abstract <T> Invoker<T> doSelect(List<Invoker<T>> invokers, URL url, Invocation invocation);

/**
 * Pick one invoker from a pre-filtered candidate set using weighted random selection.
 * Used by load balancers that first narrow the field to a "best" tier (e.g. least-active,
 * shortest-response) and then apply the same weighted-random tiebreak.
 */
protected static <T> Invoker<T> selectWithWeight(
        List<Invoker<T>> invokers,
        int[] candidateIndexes,
        int candidateCount,
        int[] weights,
        boolean sameWeight,
        int totalWeight) {
    if (candidateCount == 1) {
        return invokers.get(candidateIndexes[0]);
    }
    if (!sameWeight && totalWeight > 0) {
        int offsetWeight = ThreadLocalRandom.current().nextInt(totalWeight);
        for (int i = 0; i < candidateCount; i++) {
            int idx = candidateIndexes[i];
            offsetWeight -= weights[idx];
            if (offsetWeight < 0) {
                return invokers.get(idx);
            }
        }
    }
    return invokers.get(candidateIndexes[ThreadLocalRandom.current().nextInt(candidateCount)]);
}

