26	
27	/**
28	 * LeastActiveLoadBalance
29	 * <p>
30	 * Filter the number of invokers with the least number of active calls and count the weights and quantities of these invokers.
31	 * If there is only one invoker, use the invoker directly;
32	 * If there are multiple invokers and the weights are not the same, then random according to the total weight;
33	 * If there are multiple invokers and the same weight, then randomly called.
34	 */
35	public class LeastActiveLoadBalance extends AbstractLoadBalance {
36	
37	    public static final String NAME = "leastactive";
38	
39	    @Override
40	    protected <T> Invoker<T> doSelect(List<Invoker<T>> invokers, URL url, Invocation invocation) {
41	        // Number of invokers
42	        int length = invokers.size();
43	        // The least active value of all invokers
44	        int leastActive = -1;
45	        // The number of invokers having the same least active value (leastActive)
46	        int leastCount = 0;
47	        // The index of invokers having the same least active value (leastActive)
48	        int[] leastIndexes = new int[length];
49	        // the weight of every invokers
50	        int[] weights = new int[length];
51	        // The sum of the warmup weights of all the least active invokers
52	        int totalWeight = 0;
53	        // The weight of the first least active invoker
54	        int firstWeight = 0;
55	        // Every least active invoker has the same weight value?
56	        boolean sameWeight = true;
57	
58	        // Filter out all the least active invokers
59	        for (int i = 0; i < length; i++) {
60	            Invoker<T> invoker = invokers.get(i);
61	            // Get the active number of the invoker
62	            int active = RpcStatus.getStatus(invoker.getUrl(), RpcUtils.getMethodName(invocation))
63	                    .getActive();
64	            // Get the weight of the invoker's configuration. The default value is 100.
65	            int afterWarmup = getWeight(invoker, invocation);
66	            // save for later use
67	            weights[i] = afterWarmup;
68	            // If it is the first invoker or the active number of the invoker is less than the current least active
69	            // number
70	            if (leastActive == -1 || active < leastActive) {
71	                // Reset the active number of the current invoker to the least active number
72	                leastActive = active;
73	                // Reset the number of least active invokers
74	                leastCount = 1;
75	                // Put the first least active invoker first in leastIndexes
76	                leastIndexes[0] = i;
77	                // Reset totalWeight
78	                totalWeight = afterWarmup;
79	                // Record the weight the first least active invoker
80	                firstWeight = afterWarmup;
81	                // Each invoke has the same weight (only one invoker here)
82	                sameWeight = true;
83	                // If current invoker's active value equals with leaseActive, then accumulating.
84	            } else if (active == leastActive) {
85	                // Record the index of the least active invoker in leastIndexes order
86	                leastIndexes[leastCount++] = i;
87	                // Accumulate the total weight of the least active invoker
88	                totalWeight += afterWarmup;
89	                // If every invoker has the same weight?
90	                if (sameWeight && afterWarmup != firstWeight) {
91	                    sameWeight = false;
92	                }
93	            }
94	        }
95	        // Choose an invoker from all the least active invokers using weighted random selection.
96	        return selectWithWeight(invokers, leastIndexes, leastCount, weights, sameWeight, totalWeight);
97	    }
98	}
