24	import com.alibaba.fastjson2.JSONB;
25	import com.alibaba.fastjson2.JSONWriter;
26	
27	/**
28	 * FastJson object output implementation
29	 */
30	public class FastJson2ObjectOutput implements ObjectOutput {
31	
32	    private final Fastjson2CreatorManager fastjson2CreatorManager;
33	
34	    private final Fastjson2SecurityManager fastjson2SecurityManager;
35	
36	    private volatile ClassLoader classLoader;
37	    private final OutputStream os;
38	
39	    public FastJson2ObjectOutput(
40	            Fastjson2CreatorManager fastjson2CreatorManager,
41	            Fastjson2SecurityManager fastjson2SecurityManager,
42	            OutputStream out) {
43	        this.fastjson2CreatorManager = fastjson2CreatorManager;
44	        this.fastjson2SecurityManager = fastjson2SecurityManager;
45	        this.classLoader = Thread.currentThread().getContextClassLoader();
46	        this.os = out;
47	        fastjson2CreatorManager.setCreator(classLoader);
48	    }
49	
50	    @Override
51	    public void writeBool(boolean v) throws IOException {
52	        writeObject(v);
53	    }
54	
55	    @Override
56	    public void writeByte(byte v) throws IOException {
57	        writeObject(v);
58	    }
59	
60	    @Override
61	    public void writeShort(short v) throws IOException {
62	        writeObject(v);
63	    }
64	
65	    @Override
66	    public void writeInt(int v) throws IOException {
67	        writeObject(v);
68	    }
69	
70	    @Override
71	    public void writeLong(long v) throws IOException {
72	        writeObject(v);
73	    }
74	
75	    @Override
76	    public void writeFloat(float v) throws IOException {
77	        writeObject(v);
78	    }
79	
80	    @Override
81	    public void writeDouble(double v) throws IOException {
82	        writeObject(v);
83	    }
84	
85	    @Override
86	    public void writeUTF(String v) throws IOException {
87	        writeObject(v);
88	    }
89	
90	    @Override
91	    public void writeBytes(byte[] b) throws IOException {
92	        writeLength(b.length);
93	        os.write(b);
94	    }
95	
96	    @Override
97	    public void writeBytes(byte[] b, int off, int len) throws IOException {
98	        writeLength(len);
99	        os.write(b, off, len);
100	    }
101	
102	    @Override
103	    public void writeObject(Object obj) throws IOException {
104	        updateClassLoaderIfNeed();
105	        byte[] bytes;
106	        if (fastjson2SecurityManager.getSecurityFilter().isCheckSerializable()) {
107	            bytes = JSONB.toBytes(
108	                    obj,
109	                    JSONWriter.Feature.WriteClassName,
110	                    JSONWriter.Feature.FieldBased,
111	                    JSONWriter.Feature.ErrorOnNoneSerializable,
112	                    JSONWriter.Feature.ReferenceDetection,
113	                    JSONWriter.Feature.WriteNulls,
114	                    JSONWriter.Feature.NotWriteDefaultValue,
115	                    JSONWriter.Feature.NotWriteHashMapArrayListClassName,
116	                    JSONWriter.Feature.WriteNameAsSymbol);
117	        } else {
118	            bytes = JSONB.toBytes(
119	                    obj,
120	                    JSONWriter.Feature.WriteClassName,
121	                    JSONWriter.Feature.FieldBased,
122	                    JSONWriter.Feature.ReferenceDetection,
123	                    JSONWriter.Feature.WriteNulls,
124	                    JSONWriter.Feature.NotWriteDefaultValue,
125	                    JSONWriter.Feature.NotWriteHashMapArrayListClassName,
126	                    JSONWriter.Feature.WriteNameAsSymbol);
127	        }
128	        writeLength(bytes.length);
129	        os.write(bytes);
130	        os.flush();
131	    }
132	
133	    private void updateClassLoaderIfNeed() {
134	        ClassLoader currentClassLoader = Thread.currentThread().getContextClassLoader();
135	        if (currentClassLoader != classLoader) {
136	            fastjson2CreatorManager.setCreator(currentClassLoader);
137	            classLoader = currentClassLoader;
138	        }
139	    }
140	
141	    private void writeLength(int value) throws IOException {
142	        byte[] bytes = new byte[Integer.BYTES];
143	        int length = bytes.length;
144	        for (int i = 0; i < length; i++) {
145	            bytes[length - i - 1] = (byte) (value & 0xFF);
146	            value >>= 8;
147	        }
148	        os.write(bytes);
149	    }
150	
151	    @Override
152	    public void flushBuffer() throws IOException {
153	        os.flush();
154	    }
155	}
