46	public class BraveProvider implements TracerProvider {
47	
48	    private static final ErrorTypeAwareLogger LOGGER = LoggerFactory.getErrorTypeAwareLogger(BraveProvider.class);
49	
50	    private static final BraveBaggageManager BRAVE_BAGGAGE_MANAGER = new BraveBaggageManager();
51	
52	    private final ApplicationModel applicationModel;
53	    private final TracingConfig tracingConfig;
54	
55	    public BraveProvider(ApplicationModel applicationModel, TracingConfig tracingConfig) {
56	        this.applicationModel = applicationModel;
57	        this.tracingConfig = tracingConfig;
58	    }
59	
60	    @Override
61	    public Tracer getTracer() {
62	        // [Brave component] SpanHandler is a component that gets called when a span is finished.
63	        List<brave.handler.SpanHandler> spanHandlerList = getSpanHandlers();
64	
65	        String applicationName = applicationModel
66	                .getApplicationConfigManager()
67	                .getApplication()
68	                .map(ApplicationConfig::getName)
69	                .orElse(DEFAULT_APPLICATION_NAME);
70	
71	        // [Brave component] CurrentTraceContext is a Brave component that allows you to
72	        // retrieve the current TraceContext.
73	        brave.propagation.ThreadLocalCurrentTraceContext braveCurrentTraceContext =
74	                brave.propagation.ThreadLocalCurrentTraceContext.newBuilder()
75	                        .addScopeDecorator(correlationScopeDecorator()) // Brave's automatic MDC setup
76	                        .build();
77	
78	        // [Micrometer Tracing component] A Micrometer Tracing wrapper for Brave's CurrentTraceContext
79	        CurrentTraceContext bridgeContext = new BraveCurrentTraceContext(braveCurrentTraceContext);
80	
81	        // [Brave component] Tracing is the root component that allows to configure the
82	        // tracer, handlers, context propagation etc.
83	        brave.Tracing.Builder builder = brave.Tracing.newBuilder()
84	                .currentTraceContext(braveCurrentTraceContext)
85	                .supportsJoin(false)
86	                .traceId128Bit(true)
87	                .localServiceName(applicationName)
88	                // For Baggage to work you need to provide a list of fields to propagate
89	                .propagationFactory(PropagatorFactory.getPropagationFactory(tracingConfig))
90	                .sampler(getSampler());
91	        spanHandlerList.forEach(builder::addSpanHandler);
92	
93	        brave.Tracing tracing = builder.build();
94	
95	        BravePropagatorProvider.createMicrometerPropagator(tracing);
96	
97	        // [Brave component] Tracer is a component that handles the life-cycle of a span
98	        brave.Tracer braveTracer = tracing.tracer();
99	
100	        // [Micrometer Tracing component] A Micrometer Tracing wrapper for Brave's Tracer
101	        return new BraveTracer(braveTracer, bridgeContext, BRAVE_BAGGAGE_MANAGER);
102	    }
103	
104	    private List<brave.handler.SpanHandler> getSpanHandlers() {
105	        ExporterConfig exporterConfig = tracingConfig.getTracingExporter();
106	        List<brave.handler.SpanHandler> res = new ArrayList<>();
107	        if (!isSupportBraveURLSender()) {
108	            return res;
109	        }
110	        ExporterConfig.ZipkinConfig zipkinConfig = exporterConfig.getZipkinConfig();
111	        if (zipkinConfig != null && StringUtils.isNotEmpty(zipkinConfig.getEndpoint())) {
112	            LOGGER.info("Create zipkin span handler.");
113	            res.add(ZipkinSpanHandler.getSpanHandler(applicationModel, zipkinConfig));
114	        }
115	        return res;
116	    }
117	
118	    private brave.sampler.Sampler getSampler() {
119	        return brave.sampler.Sampler.create(tracingConfig.getSampling().getProbability());
120	    }
121	
122	    private Optional<brave.baggage.CorrelationScopeCustomizer> correlationFieldsCorrelationScopeCustomizer() {
123	        BaggageConfig.Correlation correlation = tracingConfig.getBaggage().getCorrelation();
124	        boolean enabled = correlation.isEnabled();
125	        if (!enabled) {
126	            return Optional.empty();
127	        }
128	        return Optional.of((builder) -> {
129	            List<String> correlationFields = correlation.getFields();
130	            for (String field : correlationFields) {
131	                builder.add(brave.baggage.CorrelationScopeConfig.SingleCorrelationField.newBuilder(
132	                                brave.baggage.BaggageField.create(field))
133	                        .flushOnUpdate()
134	                        .build());
135	            }
136	        });
137	    }
138	
139	    private brave.propagation.CurrentTraceContext.ScopeDecorator correlationScopeDecorator() {
140	        brave.baggage.CorrelationScopeDecorator.Builder builder = brave.context.slf4j.MDCScopeDecorator.newBuilder();
141	        correlationFieldsCorrelationScopeCustomizer().ifPresent((customizer) -> customizer.customize(builder));
142	        return builder.build();
143	    }
144	
145	    static class PropagatorFactory {
146	
147	        public static brave.propagation.Propagation.Factory getPropagationFactory(TracingConfig tracingConfig) {
148	            BaggageConfig baggageConfig = tracingConfig.getBaggage();
149	            if (baggageConfig == null || !baggageConfig.getEnabled()) {
150	                return getPropagationFactoryWithoutBaggage(tracingConfig);
151	            }
152	            return getPropagationFactoryWithBaggage(tracingConfig);
153	        }
154	
155	        private static brave.propagation.Propagation.Factory getPropagationFactoryWithoutBaggage(
156	                TracingConfig tracingConfig) {
157	            PropagationType propagationType =
158	                    PropagationType.forValue(tracingConfig.getPropagation().getType());
159	            if (PropagationType.W3C == propagationType) {
160	                return new io.micrometer.tracing.brave.bridge.W3CPropagation();
161	            } else {
162	                // Brave default propagation is B3
163	                return brave.propagation.B3Propagation.newFactoryBuilder()
164	                        .injectFormat(brave.propagation.B3Propagation.Format.SINGLE_NO_PARENT)
165	                        .build();
166	            }
167	        }
168	
169	        private static brave.propagation.Propagation.Factory getPropagationFactoryWithBaggage(
170	                TracingConfig tracingConfig) {
171	            PropagationType propagationType =
172	                    PropagationType.forValue(tracingConfig.getPropagation().getType());
173	            brave.propagation.Propagation.Factory delegate;
174	            if (PropagationType.W3C == propagationType) {
175	                delegate = new W3CPropagation(BRAVE_BAGGAGE_MANAGER, Collections.emptyList());
176	            } else {
177	                // Brave default propagation is B3
178	                delegate = brave.propagation.B3Propagation.newFactoryBuilder()
179	                        .injectFormat(brave.propagation.B3Propagation.Format.SINGLE_NO_PARENT)
180	                        .build();
181	            }
182	            return getBaggageFactoryBuilder(delegate, tracingConfig).build();
183	        }
184	
185	        private static brave.baggage.BaggagePropagation.FactoryBuilder getBaggageFactoryBuilder(
186	                brave.propagation.Propagation.Factory delegate, TracingConfig tracingConfig) {
187	            brave.baggage.BaggagePropagation.FactoryBuilder builder =
188	                    brave.baggage.BaggagePropagation.newFactoryBuilder(delegate);
189	
190	            getBaggagePropagationCustomizers(tracingConfig).forEach((customizer) -> customizer.customize(builder));
191	            return builder;
192	        }
193	
194	        private static List<brave.baggage.BaggagePropagationCustomizer> getBaggagePropagationCustomizers(
195	                TracingConfig tracingConfig) {
196	            List<brave.baggage.BaggagePropagationCustomizer> res = new ArrayList<>();
197	            if (tracingConfig.getBaggage().getCorrelation().isEnabled()) {
198	                res.add(remoteFieldsBaggagePropagationCustomizer(tracingConfig));
199	            }
200	            return res;
201	        }
202	
203	        private static brave.baggage.BaggagePropagationCustomizer remoteFieldsBaggagePropagationCustomizer(
204	                TracingConfig tracingConfig) {
205	            return (builder) -> {
206	                List<String> remoteFields = tracingConfig.getBaggage().getRemoteFields();
207	                for (String fieldName : remoteFields) {
208	                    builder.add(brave.baggage.BaggagePropagationConfig.SingleBaggageField.remote(
209	                            brave.baggage.BaggageField.create(fieldName)));
210	                }
211	            };
212	        }
213	    }
214	}
