102	        } catch (Throwable ignored) {
103	        }
104	        // [OTel component] SdkTracerProvider is an SDK implementation for TracerProvider
105	        io.opentelemetry.sdk.trace.SdkTracerProvider sdkTracerProvider =
106	                io.opentelemetry.sdk.trace.SdkTracerProvider.builder()
