214	    static class PropagatorFactory {
215	
216	        public static io.opentelemetry.context.propagation.TextMapPropagator getPropagator(
217	                PropagationConfig propagationConfig,
218	                @Nullable BaggageConfig baggageConfig,
219	                @Nullable OtelCurrentTraceContext currentTraceContext) {
220	            if (baggageConfig == null || !baggageConfig.getEnabled()) {
221	                return getPropagatorWithoutBaggage(propagationConfig);
222	            }
223	            return getPropagatorWithBaggage(propagationConfig, baggageConfig, currentTraceContext);
224	        }
225	
226	        private static io.opentelemetry.context.propagation.TextMapPropagator getPropagatorWithoutBaggage(
227	                PropagationConfig propagationConfig) {
228	            String type = propagationConfig.getType();
229	            PropagationType propagationType = PropagationType.forValue(type);
230	
231	            if (PropagationType.B3 == propagationType) {
232	                return io.opentelemetry.extension.trace.propagation.B3Propagator.injectingSingleHeader();
233	            } else if (PropagationType.W3C == propagationType) {
234	                return io.opentelemetry.api.trace.propagation.W3CTraceContextPropagator.getInstance();
235	            }
236	            return io.opentelemetry.context.propagation.TextMapPropagator.noop();
237	        }
238	
239	        private static io.opentelemetry.context.propagation.TextMapPropagator getPropagatorWithBaggage(
240	                PropagationConfig propagationConfig,
241	                BaggageConfig baggageConfig,
242	                OtelCurrentTraceContext currentTraceContext) {
243	            String type = propagationConfig.getType();
244	            PropagationType propagationType = PropagationType.forValue(type);
245	            if (PropagationType.B3 == propagationType) {
246	                List<String> remoteFields = baggageConfig.getRemoteFields();
247	                return io.opentelemetry.context.propagation.TextMapPropagator.composite(
248	                        io.opentelemetry.extension.trace.propagation.B3Propagator.injectingSingleHeader(),
249	                        new BaggageTextMapPropagator(
250	                                remoteFields,
251	                                new OtelBaggageManager(currentTraceContext, remoteFields, Collections.emptyList())));
252	            } else if (PropagationType.W3C == propagationType) {
253	                List<String> remoteFields = baggageConfig.getRemoteFields();
254	                return io.opentelemetry.context.propagation.TextMapPropagator.composite(
255	                        io.opentelemetry.api.trace.propagation.W3CTraceContextPropagator.getInstance(),
256	                        io.opentelemetry.api.baggage.propagation.W3CBaggagePropagator.getInstance(),
257	                        new BaggageTextMapPropagator(
258	                                remoteFields,
259	                                new OtelBaggageManager(currentTraceContext, remoteFields, Collections.emptyList())));
260	            }
261	            return io.opentelemetry.context.propagation.TextMapPropagator.noop();
262	        }
263	    }
