21	import org.apache.dubbo.common.utils.ConcurrentHashMapUtils;
22	import org.apache.dubbo.rpc.Invocation;
23	import org.apache.dubbo.rpc.Invoker;
24	import org.apache.dubbo.rpc.RpcStatus;
25	import org.apache.dubbo.rpc.cluster.Constants;
26	import org.apache.dubbo.rpc.model.ApplicationModel;
27	import org.apache.dubbo.rpc.model.ScopeModelAware;
28	import org.apache.dubbo.rpc.support.RpcUtils;
29	
30	import java.util.List;
31	import java.util.concurrent.ConcurrentHashMap;
32	import java.util.concurrent.ConcurrentMap;
33	import java.util.concurrent.ExecutorService;
34	import java.util.concurrent.atomic.AtomicBoolean;
35	
36	/**
37	 * ShortestResponseLoadBalance
38	 * </p>
39	 * Filter the number of invokers with the shortest response time of
40	 * success calls and count the weights and quantities of these invokers in last slide window.
41	 * If there is only one invoker, use the invoker directly;
42	 * If there are multiple invokers and the weights are not the same, then random according to the total weight;
43	 * If there are multiple invokers and the same weight, then randomly called.
44	 */
45	public class ShortestResponseLoadBalance extends AbstractLoadBalance implements ScopeModelAware {
46	
47	    public static final String NAME = "shortestresponse";
48	
49	    private int slidePeriod = 30_000;
50	
51	    private final ConcurrentMap<RpcStatus, SlideWindowData> methodMap = new ConcurrentHashMap<>();
52	
53	    private final AtomicBoolean onResetSlideWindow = new AtomicBoolean(false);
54	
55	    private volatile long lastUpdateTime = System.currentTimeMillis();
56	
57	    private ExecutorService executorService;
58	
59	    @Override
60	    public void setApplicationModel(ApplicationModel applicationModel) {
61	        slidePeriod = applicationModel
62	                .modelEnvironment()
63	                .getConfiguration()
64	                .getInt(Constants.SHORTEST_RESPONSE_SLIDE_PERIOD, 30_000);
65	        executorService = applicationModel
66	                .getFrameworkModel()
67	                .getBeanFactory()
68	                .getBean(FrameworkExecutorRepository.class)
69	                .getSharedExecutor();
70	    }
71	
72	    protected static class SlideWindowData {
73	
74	        private long succeededOffset;
75	        private long succeededElapsedOffset;
76	        private final RpcStatus rpcStatus;
77	
78	        public SlideWindowData(RpcStatus rpcStatus) {
79	            this.rpcStatus = rpcStatus;
80	            this.succeededOffset = 0;
81	            this.succeededElapsedOffset = 0;
82	        }
83	
84	        public void reset() {
85	            this.succeededOffset = rpcStatus.getSucceeded();
86	            this.succeededElapsedOffset = rpcStatus.getSucceededElapsed();
87	        }
88	
89	        private long getSucceededAverageElapsed() {
90	            long succeed = this.rpcStatus.getSucceeded() - this.succeededOffset;
91	            if (succeed == 0) {
92	                return 0;
93	            }
94	            return (this.rpcStatus.getSucceededElapsed() - this.succeededElapsedOffset) / succeed;
95	        }
96	
97	        public long getEstimateResponse() {
98	            int active = this.rpcStatus.getActive() + 1;
99	            return getSucceededAverageElapsed() * active;
100	        }
101	    }
102	
103	    @Override
104	    protected <T> Invoker<T> doSelect(List<Invoker<T>> invokers, URL url, Invocation invocation) {
105	        // Number of invokers
106	        int length = invokers.size();
107	        // Estimated shortest response time of all invokers
108	        long shortestResponse = Long.MAX_VALUE;
109	        // The number of invokers having the same estimated shortest response time
110	        int shortestCount = 0;
111	        // The index of invokers having the same estimated shortest response time
112	        int[] shortestIndexes = new int[length];
113	        // the weight of every invokers
114	        int[] weights = new int[length];
115	        // The sum of the warmup weights of all the shortest response  invokers
116	        int totalWeight = 0;
117	        // The weight of the first shortest response invokers
118	        int firstWeight = 0;
119	        // Every shortest response invoker has the same weight value?
120	        boolean sameWeight = true;
121	
122	        // Filter out all the shortest response invokers
123	        for (int i = 0; i < length; i++) {
124	            Invoker<T> invoker = invokers.get(i);
125	            RpcStatus rpcStatus = RpcStatus.getStatus(invoker.getUrl(), RpcUtils.getMethodName(invocation));
126	            SlideWindowData slideWindowData =
127	                    ConcurrentHashMapUtils.computeIfAbsent(methodMap, rpcStatus, SlideWindowData::new);
128	
129	            // Calculate the estimated response time from the product of active connections and succeeded average
130	            // elapsed time.
131	            long estimateResponse = slideWindowData.getEstimateResponse();
132	            int afterWarmup = getWeight(invoker, invocation);
133	            weights[i] = afterWarmup;
134	            // Same as LeastActiveLoadBalance
135	            if (estimateResponse < shortestResponse) {
136	                shortestResponse = estimateResponse;
137	                shortestCount = 1;
138	                shortestIndexes[0] = i;
139	                totalWeight = afterWarmup;
140	                firstWeight = afterWarmup;
141	                sameWeight = true;
142	            } else if (estimateResponse == shortestResponse) {
143	                shortestIndexes[shortestCount++] = i;
144	                totalWeight += afterWarmup;
145	                if (sameWeight && i > 0 && afterWarmup != firstWeight) {
146	                    sameWeight = false;
147	                }
148	            }
149	        }
150	
151	        if (System.currentTimeMillis() - lastUpdateTime > slidePeriod
152	                && onResetSlideWindow.compareAndSet(false, true)) {
153	            // reset slideWindowData in async way
154	            executorService.execute(() -> {
155	                methodMap.values().forEach(SlideWindowData::reset);
156	                lastUpdateTime = System.currentTimeMillis();
157	                onResetSlideWindow.set(false);
158	            });
159	        }
160	
161	        return selectWithWeight(invokers, shortestIndexes, shortestCount, weights, sameWeight, totalWeight);
162	    }
163	}
