39	@Activate
40	public class ArgumentConditionMatcher extends AbstractConditionMatcher {
41	    private static final ErrorTypeAwareLogger logger =
42	            LoggerFactory.getErrorTypeAwareLogger(ArgumentConditionMatcher.class);
