17	package org.apache.dubbo.common.utils;
18	
19	import java.util.HashMap;
20	import java.util.Map;
21	import java.util.concurrent.locks.ReentrantLock;
22	
23	public class LFUCache<K, V> {
24	
25	    private final Map<K, CacheNode<K, V>> map;
26	    private final CacheDeque<K, V>[] freqTable;
27	
28	    private final int capacity;
29	    private final int evictionCount;
30	    private int curSize = 0;
31	
32	    private final ReentrantLock lock = new ReentrantLock();
33	    private static final int DEFAULT_INITIAL_CAPACITY = 1000;
34	
35	    private static final float DEFAULT_EVICTION_FACTOR = 0.75f;
36	
37	    public LFUCache() {
38	        this(DEFAULT_INITIAL_CAPACITY, DEFAULT_EVICTION_FACTOR);
39	    }
40	
41	    /**
42	     * Constructs and initializes cache with specified capacity and eviction
43	     * factor. Unacceptable parameter values followed with
44	     * {@link IllegalArgumentException}.
45	     *
46	     * @param maxCapacity    cache max capacity
47	     * @param evictionFactor cache proceedEviction factor
48	     */
49	    @SuppressWarnings("unchecked")
50	    public LFUCache(final int maxCapacity, final float evictionFactor) {
51	        if (maxCapacity <= 0) {
52	            throw new IllegalArgumentException("Illegal initial capacity: " + maxCapacity);
53	        }
54	        boolean factorInRange = evictionFactor <= 1 && evictionFactor > 0;
55	        if (!factorInRange || Float.isNaN(evictionFactor)) {
56	            throw new IllegalArgumentException("Illegal eviction factor value:" + evictionFactor);
57	        }
58	        this.capacity = maxCapacity;
59	        this.evictionCount = (int) (capacity * evictionFactor);
60	        this.map = new HashMap<>();
61	        this.freqTable = new CacheDeque[capacity + 1];
62	        for (int i = 0; i <= capacity; i++) {
63	            freqTable[i] = new CacheDeque<>();
64	        }
65	        for (int i = 0; i < capacity; i++) {
66	            freqTable[i].nextDeque = freqTable[i + 1];
67	        }
68	        freqTable[capacity].nextDeque = freqTable[capacity];
69	    }
70	
71	    public int getCapacity() {
72	        return capacity;
73	    }
74	
75	    public V put(final K key, final V value) {
76	        CacheNode<K, V> node;
77	        lock.lock();
78	        try {
79	            node = map.get(key);
80	            if (node != null) {
81	                CacheNode.withdrawNode(node);
82	                node.value = value;
83	                freqTable[0].addLastNode(node);
84	                map.put(key, node);
85	            } else {
86	                curSize++;
87	                if (curSize > capacity) {
88	                    proceedEviction();
89	                }
90	                node = freqTable[0].addLast(key, value);
91	                map.put(key, node);
92	            }
93	        } finally {
94	            lock.unlock();
95	        }
96	        return node.value;
97	    }
98	
99	    public V remove(final K key) {
100	        CacheNode<K, V> node = null;
101	        lock.lock();
102	        try {
103	            if (map.containsKey(key)) {
104	                node = map.remove(key);
105	                if (node != null) {
106	                    CacheNode.withdrawNode(node);
107	                }
108	                curSize--;
109	            }
110	        } finally {
111	            lock.unlock();
112	        }
113	        return (node != null) ? node.value : null;
114	    }
115	
116	    public V get(final K key) {
117	        CacheNode<K, V> node = null;
118	        lock.lock();
119	        try {
120	            if (map.containsKey(key)) {
121	                node = map.get(key);
122	                CacheNode.withdrawNode(node);
123	                node.owner.nextDeque.addLastNode(node);
124	            }
125	        } finally {
126	            lock.unlock();
127	        }
128	        return (node != null) ? node.value : null;
129	    }
130	
131	    /**
132	     * Evicts less frequently used elements corresponding to eviction factor,
133	     * specified at instantiation step.
134	     *
135	     * @return number of evicted elements
136	     */
137	    private int proceedEviction() {
138	        int targetSize = capacity - evictionCount;
139	        int evictedElements = 0;
140	
141	        FREQ_TABLE_ITER_LOOP:
142	        for (int i = 0; i <= capacity; i++) {
143	            CacheNode<K, V> node;
144	            while (!freqTable[i].isEmpty()) {
145	                node = freqTable[i].pollFirst();
146	                remove(node.key);
147	                if (targetSize >= curSize) {
148	                    break FREQ_TABLE_ITER_LOOP;
149	                }
150	                evictedElements++;
151	            }
152	        }
153	        return evictedElements;
154	    }
155	
156	    /**
157	     * Returns cache current size.
158	     *
159	     * @return cache size
160	     */
161	    public int getSize() {
162	        return curSize;
163	    }
164	
165	    static class CacheNode<K, V> {
166	
167	        CacheNode<K, V> prev;
168	        CacheNode<K, V> next;
169	        K key;
170	        V value;
171	        CacheDeque<K, V> owner;
172	
173	        CacheNode() {}
174	
175	        CacheNode(final K key, final V value) {
176	            this.key = key;
177	            this.value = value;
178	        }
179	
180	        /**
181	         * This method takes specified node and reattaches it neighbors nodes
182	         * links to each other, so specified node will no longer tied with them.
183	         * Returns united node, returns null if argument is null.
184	         *
185	         * @param node note to retrieve
186	         * @param <K>  key
187	         * @param <V>  value
188	         * @return retrieved node
189	         */
190	        static <K, V> CacheNode<K, V> withdrawNode(final CacheNode<K, V> node) {
191	            if (node != null && node.prev != null) {
192	                node.prev.next = node.next;
193	                if (node.next != null) {
194	                    node.next.prev = node.prev;
195	                }
196	            }
197	            return node;
198	        }
199	    }
200	
201	    /**
202	     * Custom deque implementation of LIFO type. Allows to place element at top
203	     * of deque and poll very last added elements. An arbitrary node from the
204	     * deque can be removed with {@link CacheNode#withdrawNode(CacheNode)}
205	     * method.
206	     *
207	     * @param <K> key
208	     * @param <V> value
209	     */
210	    static class CacheDeque<K, V> {
211	
212	        CacheNode<K, V> last;
213	        CacheNode<K, V> first;
214	        CacheDeque<K, V> nextDeque;
215	
216	        /**
217	         * Constructs list and initializes last and first pointers.
218	         */
219	        CacheDeque() {
220	            last = new CacheNode<>();
221	            first = new CacheNode<>();
222	            last.next = first;
223	            first.prev = last;
224	        }
225	
226	        /**
227	         * Puts the node with specified key and value at the end of the deque
228	         * and returns node.
229	         *
230	         * @param key   key
231	         * @param value value
232	         * @return added node
233	         */
234	        CacheNode<K, V> addLast(final K key, final V value) {
235	            CacheNode<K, V> node = new CacheNode<>(key, value);
236	            node.owner = this;
237	            node.next = last.next;
238	            node.prev = last;
239	            node.next.prev = node;
240	            last.next = node;
241	            return node;
242	        }
243	
244	        CacheNode<K, V> addLastNode(final CacheNode<K, V> node) {
245	            node.owner = this;
246	            node.next = last.next;
247	            node.prev = last;
248	            node.next.prev = node;
249	            last.next = node;
250	            return node;
251	        }
252	
253	        /**
254	         * Retrieves and removes the first node of this deque.
255	         *
256	         * @return removed node
257	         */
258	        CacheNode<K, V> pollFirst() {
259	            CacheNode<K, V> node = null;
260	            if (first.prev != last) {
261	                node = first.prev;
262	                first.prev = node.prev;
263	                first.prev.next = first;
264	                node.prev = null;
265	                node.next = null;
266	            }
267	            return node;
268	        }
269	
270	        /**
271	         * Checks if link to the last node points to link to the first node.
272	         *
273	         * @return is deque empty
274	         */
275	        boolean isEmpty() {
276	            return last.next == first;
277	        }
278	    }
279	}
