129	    @Override
130	    public void subscribe(URL url) {
131	
132	        // Fail-fast detection protocol spi
133	        String queryProtocols = this.queryMap.get(PROTOCOL_KEY);
134	        if (StringUtils.isNotBlank(queryProtocols)) {
135	            String[] acceptProtocols = queryProtocols.split(",");
136	            for (String acceptProtocol : acceptProtocols) {
137	                if (!moduleModel
138	                        .getApplicationModel()
139	                        .getExtensionLoader(Protocol.class)
140	                        .hasExtension(acceptProtocol)) {
141	                    throw new IllegalStateException("No such extension org.apache.dubbo.rpc.Protocol by name "
142	                            + acceptProtocol + ",  please check whether related SPI module is missing");
143	                }
144	            }
145	        }
146	
147	        ApplicationModel applicationModel = url.getApplicationModel();
148	        if (moduleModel
149	                .modelEnvironment()
150	                .getConfiguration()
151	                .convert(Boolean.class, org.apache.dubbo.registry.Constants.ENABLE_CONFIGURATION_LISTEN, true)) {
152	            consumerConfigurationListener.addNotifyListener(this);
153	            referenceConfigurationListener = new ReferenceConfigurationListener(moduleModel, this, url);
154	        }
155	        String registryClusterName = registry.getUrl()
156	                .getParameter(
157	                        RegistryConstants.REGISTRY_CLUSTER_KEY,
158	                        registry.getUrl().getParameter(PROTOCOL_KEY));
159	        MetricsEventBus.post(RegistryEvent.toSubscribeEvent(applicationModel, registryClusterName), () -> {
160	            super.subscribe(url);
161	            return null;
162	        });
163	    }
