200	    @Override
201	    public synchronized void notify(List<URL> urls) {
202	        if (isDestroyed()) {
203	            return;
204	        }
205	
206	        Map<String, List<URL>> categoryUrls = urls.stream()
207	                .filter(Objects::nonNull)
208	                .filter(this::isValidCategory)
209	                .filter(this::isNotCompatibleFor26x)
210	                .collect(Collectors.groupingBy(this::judgeCategory));
211	
212	        if (moduleModel
213	                .modelEnvironment()
214	                .getConfiguration()
215	                .convert(Boolean.class, ENABLE_26X_CONFIGURATION_LISTEN, true)) {
216	            List<URL> configuratorURLs = categoryUrls.getOrDefault(CONFIGURATORS_CATEGORY, Collections.emptyList());
217	            this.configurators = Configurator.toConfigurators(configuratorURLs).orElse(this.configurators);
218	
219	            List<URL> routerURLs = categoryUrls.getOrDefault(ROUTERS_CATEGORY, Collections.emptyList());
220	            toRouters(routerURLs).ifPresent(this::addRouters);
221	        }
222	
223	        // providers
224	        List<URL> providerURLs = categoryUrls.getOrDefault(PROVIDERS_CATEGORY, Collections.emptyList());
225	
226	        // 3.x added for extend URL address
227	        ExtensionLoader<AddressListener> addressListenerExtensionLoader =
228	                getUrl().getOrDefaultModuleModel().getExtensionLoader(AddressListener.class);
229	        List<AddressListener> supportedListeners =
230	                addressListenerExtensionLoader.getActivateExtension(getUrl(), (String[]) null);
231	        if (supportedListeners != null && !supportedListeners.isEmpty()) {
232	            for (AddressListener addressListener : supportedListeners) {
233	                providerURLs = addressListener.notify(providerURLs, getConsumerUrl(), this);
234	            }
235	        }
236	        refreshOverrideAndInvoker(providerURLs);
237	    }
