263	    /**
264	     * Convert the invokerURL list to the Invoker Map. The rules of the conversion are as follows:
265	     * <ol>
266	     * <li> If URL has been converted to invoker, it is no longer re-referenced and obtained directly from the cache,
267	     * and notice that any parameter changes in the URL will be re-referenced.</li>
268	     * <li>If the incoming invoker list is not empty, it means that it is the latest invoker list.</li>
269	     * <li>If the list of incoming invokerUrl is empty, It means that the rule is only a override rule or a route
270	     * rule, which needs to be re-contrasted to decide whether to re-reference.</li>
271	     * </ol>
272	     *
273	     * @param invokerUrls this parameter can't be null
274	     */
275	    private void refreshInvoker(List<URL> invokerUrls) {
276	        Assert.notNull(invokerUrls, "invokerUrls should not be null");
277	
278	        if (invokerUrls.size() == 1
279	                && invokerUrls.get(0) != null
280	                && EMPTY_PROTOCOL.equals(invokerUrls.get(0).getProtocol())) {
281	            refreshRouter(
282	                    BitList.emptyList(), () -> this.forbidden = true // Forbid to access
283	                    );
284	            destroyAllInvokers(); // Close all invokers
285	        } else {
286	            this.forbidden = false; // Allow to access
287	
288	            if (invokerUrls == Collections.<URL>emptyList()) {
289	                invokerUrls = new ArrayList<>();
290	            }
291	            // use local reference to avoid NPE as this.cachedInvokerUrls will be set null by destroyAllInvokers().
292	            Set<URL> localCachedInvokerUrls = this.cachedInvokerUrls;
293	            if (invokerUrls.isEmpty()) {
294	                if (CollectionUtils.isNotEmpty(localCachedInvokerUrls)) {
295	                    // 1-4 Empty address.
296	                    logger.warn(
297	                            REGISTRY_EMPTY_ADDRESS,
298	                            "configuration ",
299	                            "",
300	                            "Service" + serviceKey
301	                                    + " received empty address list with no EMPTY protocol set, trigger empty protection.");
302	
303	                    invokerUrls.addAll(localCachedInvokerUrls);
304	                }
305	            } else {
306	                localCachedInvokerUrls = new HashSet<>();
307	                localCachedInvokerUrls.addAll(invokerUrls); // Cached invoker urls, convenient for comparison
308	                this.cachedInvokerUrls = localCachedInvokerUrls;
309	            }
310	            if (invokerUrls.isEmpty()) {
311	                return;
312	            }
313	
314	            int originSize = invokerUrls.size();
315	            invokerUrls = invokerUrls.stream().distinct().collect(Collectors.toList());
316	            if (invokerUrls.size() != originSize) {
317	                logger.info("Received duplicated invoker urls changed event from registry. "
318	                        + "Registry type: interface. "
319	                        + "Service Key: "
320	                        + getConsumerUrl().getServiceKey() + ". "
321	                        + "Notify Urls Size : " + originSize + ". "
322	                        + "Distinct Urls Size: " + invokerUrls.size() + ".");
323	            }
324	
325	            // use local reference to avoid NPE as this.urlInvokerMap will be set null concurrently at
326	            // destroyAllInvokers().
327	            Map<URL, Invoker<T>> localUrlInvokerMap = this.urlInvokerMap;
328	            // can't use local reference as oldUrlInvokerMap's mappings might be removed directly at toInvokers().
329	            Map<URL, Invoker<T>> oldUrlInvokerMap = null;
330	            if (localUrlInvokerMap != null) {
331	                // the initial capacity should be set greater than the maximum number of entries divided by the load
332	                // factor to avoid resizing.
333	                oldUrlInvokerMap =
334	                        new LinkedHashMap<>(Math.round(1 + localUrlInvokerMap.size() / DEFAULT_HASHMAP_LOAD_FACTOR));
335	                localUrlInvokerMap.forEach(oldUrlInvokerMap::put);
336	            }
337	            Map<URL, Invoker<T>> newUrlInvokerMap =
338	                    toInvokers(oldUrlInvokerMap, invokerUrls); // Translate url list to Invoker map
339	
340	            /*
341	             * If the calculation is wrong, it is not processed.
342	             *
343	             * 1. The protocol configured by the client is inconsistent with the protocol of the server.
344	             *    eg: consumer protocol = dubbo, provider only has other protocol services(rest).
345	             * 2. The registration center is not robust and pushes illegal specification data.
346	             *
347	             */
348	            if (CollectionUtils.isEmptyMap(newUrlInvokerMap)) {
349	
350	                // 3-1 - Failed to convert the URL address into Invokers.
351	
352	                logger.error(
353	                        PROXY_FAILED_CONVERT_URL,
354	                        "inconsistency between the client protocol and the protocol of the server",
355	                        "",
356	                        "urls to invokers error",
357	                        new IllegalStateException("urls to invokers error. invokerUrls.size :" + invokerUrls.size()
358	                                + ", invoker.size :0. urls :" + invokerUrls.toString()));
359	
360	                return;
361	            }
362	
363	            List<Invoker<T>> newInvokers = Collections.unmodifiableList(new ArrayList<>(newUrlInvokerMap.values()));
364	            BitList<Invoker<T>> finalInvokers =
365	                    multiGroup ? new BitList<>(toMergeInvokerList(newInvokers)) : new BitList<>(newInvokers);
366	            // pre-route and build cache
367	            refreshRouter(finalInvokers.clone(), () -> this.setInvokers(finalInvokers));
368	            this.urlInvokerMap = newUrlInvokerMap;
369	
370	            try {
371	                destroyUnusedInvokers(oldUrlInvokerMap, newUrlInvokerMap); // Close the unused Invoker
372	            } catch (Exception e) {
373	                logger.warn(REGISTRY_FAILED_DESTROY_SERVICE, "", "", "destroyUnusedInvokers error. ", e);
374	            }
375	
376	            // notify invokers refreshed
377	            this.invokersChanged();
378	        }
379	
380	        logger.info("Received invokers changed event from registry. " + "Registry type: interface. "
381	                + "Service Key: "
382	                + getConsumerUrl().getServiceKey() + ". " + "Urls Size : "
383	                + invokerUrls.size() + ". " + "Invokers Size : "
384	                + getInvokers().size() + ". " + "Available Size: "
385	                + getValidInvokers().size() + ". " + "Available Invokers : "
386	                + joinValidInvokerAddresses());
387	    }
