389	    private List<Invoker<T>> toMergeInvokerList(List<Invoker<T>> invokers) {
390	        List<Invoker<T>> mergedInvokers = new ArrayList<>();
391	        Map<String, List<Invoker<T>>> groupMap = new HashMap<>();
392	        for (Invoker<T> invoker : invokers) {
393	            String group = invoker.getUrl().getGroup("");
394	            groupMap.computeIfAbsent(group, k -> new ArrayList<>());
395	            groupMap.get(group).add(invoker);
396	        }
397	
398	        if (groupMap.size() == 1) {
399	            mergedInvokers.addAll(groupMap.values().iterator().next());
400	        } else if (groupMap.size() > 1) {
401	            for (List<Invoker<T>> groupList : groupMap.values()) {
402	                StaticDirectory<T> staticDirectory = new StaticDirectory<>(groupList);
403	                staticDirectory.buildRouterChain();
404	                mergedInvokers.add(cluster.join(staticDirectory, false));
405	            }
406	        } else {
407	            mergedInvokers = invokers;
408	        }
409	        return mergedInvokers;
410	    }
