412	    /**
413	     * @param urls
414	     * @return null : no routers ,do nothing
415	     * else :routers list
416	     */
417	    private Optional<List<Router>> toRouters(List<URL> urls) {
418	        if (urls == null || urls.isEmpty()) {
419	            return Optional.empty();
420	        }
421	
422	        List<Router> routers = new ArrayList<>();
423	        for (URL url : urls) {
424	            if (EMPTY_PROTOCOL.equals(url.getProtocol())) {
425	                continue;
426	            }
427	            String routerType = url.getParameter(ROUTER_KEY);
428	            if (routerType != null && routerType.length() > 0) {
429	                url = url.setProtocol(routerType);
430	            }
431	            try {
432	                Router router = routerFactory.getRouter(url);
433	                if (!routers.contains(router)) {
434	                    routers.add(router);
435	                }
436	            } catch (Throwable t) {
437	                logger.error(PROXY_FAILED_CONVERT_URL, "", "", "convert router url to router error, url:" + url, t);
438	            }
439	        }
440	
441	        return Optional.of(routers);
442	    }
