444	    /**
445	     * Turn urls into invokers, and if url has been referred, will not re-reference.
446	     * the items that will be put into newUrlInvokeMap will be removed from oldUrlInvokerMap.
447	     *
448	     * @param oldUrlInvokerMap it might be modified during the process.
449	     * @param urls
450	     * @return invokers
451	     */
452	    private Map<URL, Invoker<T>> toInvokers(Map<URL, Invoker<T>> oldUrlInvokerMap, List<URL> urls) {
453	        Map<URL, Invoker<T>> newUrlInvokerMap =
454	                new ConcurrentHashMap<>(urls == null ? 1 : (int) (urls.size() / 0.75f + 1));
455	        if (urls == null || urls.isEmpty()) {
456	            return newUrlInvokerMap;
457	        }
458	        String queryProtocols = this.queryMap.get(PROTOCOL_KEY);
459	        for (URL providerUrl : urls) {
460	            if (!checkProtocolValid(queryProtocols, providerUrl)) {
461	                continue;
462	            }
463	
464	            URL url = mergeUrl(providerUrl);
465	            // get the effective protocol that this consumer should consume based on consumer side protocol
466	            // configuration and available protocols in address pool.
467	            String effectiveProtocol = getEffectiveProtocol(queryProtocols, url);
468	            if (!effectiveProtocol.equals(url.getProtocol())) {
469	                url = url.setProtocol(effectiveProtocol);
470	            }
471	
472	            // Cache key is url that does not merge with consumer side parameters,
473	            // regardless of how the consumer combines parameters,
474	            // if the server url changes, then refer again
475	            Invoker<T> invoker = oldUrlInvokerMap == null ? null : oldUrlInvokerMap.remove(url);
476	            if (invoker == null) { // Not in the cache, refer again
477	                try {
478	                    boolean enabled = true;
479	                    if (url.hasParameter(DISABLED_KEY)) {
480	                        enabled = !url.getParameter(DISABLED_KEY, false);
481	                    } else {
482	                        enabled = url.getParameter(ENABLED_KEY, true);
483	                    }
484	                    if (enabled) {
485	                        invoker = protocol.refer(serviceType, url);
486	                    }
487	                } catch (Throwable t) {
488	
489	                    // Thrown by AbstractProtocol.optimizeSerialization()
490	                    if (t instanceof RpcException && t.getMessage().contains("serialization optimizer")) {
491	                        // 4-2 - serialization optimizer class initialization failed.
492	                        logger.error(
493	                                PROTOCOL_FAILED_INIT_SERIALIZATION_OPTIMIZER,
494	                                "typo in optimizer class",
495	                                "",
496	                                "Failed to refer invoker for interface:" + serviceType + ",url:(" + url + ")"
497	                                        + t.getMessage(),
498	                                t);
499	
500	                    } else {
501	                        // 4-3 - Failed to refer invoker by other reason.
502	                        logger.error(
503	                                PROTOCOL_FAILED_REFER_INVOKER,
504	                                "",
505	                                "",
506	                                "Failed to refer invoker for interface:" + serviceType + ",url:(" + url + ")"
507	                                        + t.getMessage(),
508	                                t);
509	                    }
510	                }
511	                if (invoker != null) { // Put new invoker in cache
512	                    newUrlInvokerMap.put(url, invoker);
513	                }
514	            } else {
515	                newUrlInvokerMap.put(url, invoker);
516	            }
517	        }
518	        return newUrlInvokerMap;
519	    }
