521	    /**
522	     * Get the protocol to consume by matching the consumer acceptable protocols and the available provider protocols.
523	     * <p>
524	     * Only the first protocol that can match with the provider protocols will be used if consumer set to accept multiple protocols.
525	     * For example, if dubbo.consumer.protocol='tri,rest' is set and provider provides tri protocol, then consumer will use tri protocol to communicate with provider.
526	     *
527	     * @param queryProtocols consumer side protocols.
528	     * @param url            provider url that have extra protocols specified.
529	     * @return the protocol to consume.
530	     */
531	    private String getEffectiveProtocol(String queryProtocols, URL url) {
532	        String protocol = url.getProtocol();
533	        String prioritizedProtocol = url.getParameter(PREFERRED_PROTOCOL, protocol);
534	
535	        String effectiveProtocol = prioritizedProtocol;
536	
537	        if (StringUtils.isNotEmpty(queryProtocols)) {
538	            String[] acceptProtocols = queryProtocols.split(COMMA_SEPARATOR);
539	            String acceptedProtocol = acceptProtocols[0];
540	            if (!acceptedProtocol.equals(prioritizedProtocol)) {
541	                if (!acceptedProtocol.equals(protocol)) {
542	                    String extProtocols = url.getParameter(EXT_PROTOCOL);
543	                    if (StringUtils.isNotEmpty(extProtocols)) {
544	                        String[] extProtocolsArr = extProtocols.split(COMMA_SEPARATOR);
545	                        for (String p : extProtocolsArr) {
546	                            if (p.equalsIgnoreCase(acceptedProtocol)) {
547	                                effectiveProtocol = acceptedProtocol;
548	                                break;
549	                            }
550	                        }
551	                    }
552	                } else {
553	                    effectiveProtocol = protocol;
554	                }
555	            }
556	        }
557	        return effectiveProtocol;
558	    }
