560	    private boolean checkProtocolValid(String queryProtocols, URL providerUrl) {
561	        // If protocol is configured at the reference side, only the matching protocol is selected
562	        if (queryProtocols != null && queryProtocols.length() > 0) {
563	            boolean accept = false;
564	
565	            String[] acceptProtocols = queryProtocols.split(",");
566	            for (String acceptProtocol : acceptProtocols) {
567	                if (providerUrl.getProtocol().equals(acceptProtocol)) {
568	                    accept = true;
569	                    break;
570	                }
571	            }
572	
573	            if (!accept) {
574	                return false;
575	            }
576	        }
577	
578	        if (EMPTY_PROTOCOL.equals(providerUrl.getProtocol())) {
579	            return false;
580	        }
581	
582	        if (!getUrl().getOrDefaultFrameworkModel()
583	                .getExtensionLoader(Protocol.class)
584	                .hasExtension(providerUrl.getProtocol())) {
585	
586	            // 4-1 - Unsupported protocol
587	
588	            logger.error(
589	                    PROTOCOL_UNSUPPORTED,
590	                    "protocol extension does not installed",
591	                    "",
592	                    "Unsupported protocol.",
593	                    new IllegalStateException("Unsupported protocol " + providerUrl.getProtocol() + " in notified url: "
594	                            + providerUrl + " from registry " + getUrl().getAddress() + " to consumer "
595	                            + NetUtils.getLocalHost() + ", supported protocol: "
596	                            + getUrl().getOrDefaultFrameworkModel()
597	                                    .getExtensionLoader(Protocol.class)
598	                                    .getSupportedExtensions()));
599	
600	            return false;
601	        }
602	
603	        return true;
604	    }
