606	    /**
607	     * Merge url parameters. the order is: override > -D >Consumer > Provider
608	     *
609	     * @param providerUrl
610	     * @return
611	     */
612	    private URL mergeUrl(URL providerUrl) {
613	        if (providerUrl instanceof ServiceAddressURL) {
614	            providerUrl = overrideWithConfigurator(providerUrl);
615	        } else {
616	            providerUrl = moduleModel
617	                    .getApplicationModel()
618	                    .getBeanFactory()
619	                    .getBean(ClusterUtils.class)
620	                    .mergeUrl(providerUrl, queryMap); // Merge the consumer side parameters
621	            providerUrl = overrideWithConfigurator(providerUrl);
622	            providerUrl = providerUrl.addParameter(
623	                    Constants.CHECK_KEY,
624	                    String.valueOf(
625	                            false)); // Do not check whether the connection is successful or not, always create Invoker!
626	        }
627	
628	        // FIXME, kept for mock
629	        if (providerUrl.hasParameter(MOCK_KEY) || providerUrl.getAnyMethodParameter(MOCK_KEY) != null) {
630	            providerUrl = providerUrl.removeParameter(MOCK_KEY);
631	        }
632	
633	        if ((providerUrl.getPath() == null || providerUrl.getPath().length() == 0)
634	                && DUBBO_PROTOCOL.equals(providerUrl.getProtocol())) { // Compatible version 1.0
635	            // fix by tony.chenl DUBBO-44
636	            String path = directoryUrl.getServiceInterface();
637	            if (path != null) {
638	                int i = path.indexOf('/');
639	                if (i >= 0) {
640	                    path = path.substring(i + 1);
641	                }
642	                i = path.lastIndexOf(':');
643	                if (i >= 0) {
644	                    path = path.substring(0, i);
645	                }
646	                providerUrl = providerUrl.setPath(path);
647	            }
648	        }
649	        return providerUrl;
650	    }
