652	    protected URL overrideWithConfigurator(URL providerUrl) {
653	        // override url with configurator from "override://" URL for dubbo 2.6 and before
654	        providerUrl = overrideWithConfigurators(this.configurators, providerUrl);
655	
656	        // override url with configurator from "app-name.configurators"
657	        providerUrl = overrideWithConfigurators(consumerConfigurationListener.getConfigurators(), providerUrl);
658	
659	        // override url with configurator from configurators from "service-name.configurators"
660	        if (referenceConfigurationListener != null) {
661	            providerUrl = overrideWithConfigurators(referenceConfigurationListener.getConfigurators(), providerUrl);
662	        }
