667	    private URL overrideWithConfigurators(List<Configurator> configurators, URL url) {
668	        if (CollectionUtils.isNotEmpty(configurators)) {
669	            if (url instanceof DubboServiceAddressURL) {
670	                DubboServiceAddressURL interfaceAddressURL = (DubboServiceAddressURL) url;
671	                URL overriddenURL = interfaceAddressURL.getOverrideURL();
672	                if (overriddenURL == null) {
673	                    String appName = interfaceAddressURL.getApplication();
674	                    String side = interfaceAddressURL.getSide();
675	                    String group = interfaceAddressURL.getGroup();
676	                    String version = interfaceAddressURL.getVersion();
677	                    overriddenURL = URLBuilder.from(interfaceAddressURL)
678	                            .clearParameters()
679	                            .addParameter(APPLICATION_KEY, appName)
680	                            .addParameter(SIDE_KEY, side)
681	                            .addParameter(GROUP_KEY, group)
682	                            .addParameter(VERSION_KEY, version)
683	                            .build();
684	                }
685	                for (Configurator configurator : configurators) {
686	                    overriddenURL = configurator.configure(overriddenURL);
687	                }
688	                url = new DubboServiceAddressURL(
689	                        interfaceAddressURL.getUrlAddress(),
690	                        interfaceAddressURL.getUrlParam(),
691	                        interfaceAddressURL.getConsumerURL(),
692	                        (ServiceConfigURL) overriddenURL);
693	            } else {
694	                for (Configurator configurator : configurators) {
695	                    url = configurator.configure(url);
696	                }
697	            }
698	        }
699	        return url;
700	    }
