730	    private void destroyUnusedInvokers(Map<URL, Invoker<T>> oldUrlInvokerMap, Map<URL, Invoker<T>> newUrlInvokerMap) {
731	        if (CollectionUtils.isEmptyMap(newUrlInvokerMap)) {
732	            destroyAllInvokers();
733	            return;
