736	        if (CollectionUtils.isEmptyMap(oldUrlInvokerMap)) {
737	            return;
738	        }
739	
740	        for (Map.Entry<URL, Invoker<T>> entry : oldUrlInvokerMap.entrySet()) {
741	            Invoker<T> invoker = entry.getValue();
742	            if (invoker != null) {
