751	                            "",
752	                            "",
753	                            "destroy invoker[" + invoker.getUrl() + "] failed. " + e.getMessage(),
754	                            e);
755	                }
756	            }
757	        }
758	
759	        logger.info(
760	                "New url total size, " + newUrlInvokerMap.size() + ", destroyed total size " + oldUrlInvokerMap.size());
761	    }
