256	                url = new DubboServiceAddressURL(
257	                        interfaceAddressURL.getUrlAddress(),
258	                        interfaceAddressURL.getUrlParam(),
259	                        interfaceAddressURL.getConsumerURL(),
260	                        (ServiceConfigURL) overriddenURL);
261	            } else {
262	                for (Configurator configurator : configurators) {
263	                    url = configurator.configure(url);
264	                }
265	            }
266	        }
267	        return url;
268	    }
