319	    private void refreshInvoker(List<URL> invokerUrls) {
320	        Assert.notNull(invokerUrls, "invokerUrls should not be null, use EMPTY url to clear current addresses.");
321	        this.originalUrls = invokerUrls;
322	
323	        if (invokerUrls.size() == 1 && EMPTY_PROTOCOL.equals(invokerUrls.get(0).getProtocol())) {
324	            logger.warn(
325	                    PROTOCOL_UNSUPPORTED,
326	                    "",
327	                    "",
328	                    String.format(
329	                            "Received url with EMPTY protocol from registry %s, will clear all available addresses.",
330	                            this));
331	            refreshRouter(
332	                    BitList.emptyList(), () -> this.forbidden = true // Forbid to access
333	                    );
334	            destroyAllInvokers(); // Close all invokers
335	        } else {
336	            this.forbidden = false; // Allow accessing
337	            if (CollectionUtils.isEmpty(invokerUrls)) {
338	                logger.warn(
339	                        PROTOCOL_UNSUPPORTED,
340	                        "",
341	                        "",
342	                        String.format(
343	                                "Received empty url list from registry %s, will ignore for protection purpose.", this));
344	                return;
345	            }
346	
347	            int originSize = invokerUrls.size();
348	            invokerUrls = invokerUrls.stream().distinct().collect(Collectors.toList());
349	            if (invokerUrls.size() != originSize) {
350	                logger.info("Received duplicated invoker urls changed event from registry. "
351	                        + "Registry type: instance. "
352	                        + "Service Key: "
353	                        + getConsumerUrl().getServiceKey() + ". "
354	                        + "Notify Urls Size : " + originSize + ". "
355	                        + "Distinct Urls Size: " + invokerUrls.size() + ".");
356	            }
357	
358	            // use local reference to avoid NPE as this.urlInvokerMap will be set null concurrently at
359	            // destroyAllInvokers().
360	            Map<ProtocolServiceKeyWithAddress, Invoker<T>> localUrlInvokerMap = this.urlInvokerMap;
361	            // can't use local reference as oldUrlInvokerMap's mappings might be removed directly at toInvokers().
362	            Map<ProtocolServiceKeyWithAddress, Invoker<T>> oldUrlInvokerMap = null;
363	            if (localUrlInvokerMap != null) {
364	                // the initial capacity should be set greater than the maximum number of entries divided by the load
365	                // factor to avoid resizing.
366	                oldUrlInvokerMap =
367	                        new LinkedHashMap<>(Math.round(1 + localUrlInvokerMap.size() / DEFAULT_HASHMAP_LOAD_FACTOR));
368	                localUrlInvokerMap.forEach(oldUrlInvokerMap::put);
369	            }
370	            Map<ProtocolServiceKeyWithAddress, Invoker<T>> newUrlInvokerMap =
371	                    toInvokers(oldUrlInvokerMap, invokerUrls); // Translate url list to Invoker map
372	            logger.info(String.format("Refreshed invoker size %s from registry %s", newUrlInvokerMap.size(), this));
373	
374	            if (CollectionUtils.isEmptyMap(newUrlInvokerMap)) {
375	                logger.error(
376	                        PROTOCOL_UNSUPPORTED,
377	                        "",
378	                        "",
379	                        "Unsupported protocol.",
380	                        new IllegalStateException(String.format(
381	                                "Cannot create invokers from url address list (total %s)", invokerUrls.size())));
382	                return;
383	            }
384	            List<Invoker<T>> newInvokers = Collections.unmodifiableList(new ArrayList<>(newUrlInvokerMap.values()));
385	            BitList<Invoker<T>> finalInvokers =
386	                    multiGroup ? new BitList<>(toMergeInvokerList(newInvokers)) : new BitList<>(newInvokers);
387	            // pre-route and build cache
388	            refreshRouter(finalInvokers.clone(), () -> this.setInvokers(finalInvokers));
389	            this.urlInvokerMap = newUrlInvokerMap;
390	
391	            if (oldUrlInvokerMap != null) {
392	                try {
393	                    destroyUnusedInvokers(oldUrlInvokerMap, newUrlInvokerMap); // Close the unused Invoker
394	                } catch (Exception e) {
395	                    logger.warn(PROTOCOL_FAILED_DESTROY_INVOKER, "", "", "destroyUnusedInvokers error. ", e);
396	                }
397	            }
398	        }
399	
400	        // notify invokers refreshed
401	        this.invokersChanged();
402	
403	        logger.info("Received invokers changed event from registry. " + "Registry type: instance. "
404	                + "Service Key: "
405	                + getConsumerUrl().getServiceKey() + ". " + "Urls Size : "
406	                + invokerUrls.size() + ". " + "Invokers Size : "
407	                + getInvokers().size() + ". " + "Available Size: "
408	                + getValidInvokers().size() + ". " + "Available Invokers : "
409	                + joinValidInvokerAddresses());
410	    }
