412	    /**
413	     * Turn urls into invokers, and if url has been refer, will not re-reference.
414	     * the items that will be put into newUrlInvokeMap will be removed from oldUrlInvokerMap.
415	     *
416	     * @param oldUrlInvokerMap it might be modified during the process.
417	     * @param urls
418	     * @return invokers
419	     */
420	    private Map<ProtocolServiceKeyWithAddress, Invoker<T>> toInvokers(
421	            Map<ProtocolServiceKeyWithAddress, Invoker<T>> oldUrlInvokerMap, List<URL> urls) {
422	        Map<ProtocolServiceKeyWithAddress, Invoker<T>> newUrlInvokerMap =
423	                new ConcurrentHashMap<>(urls == null ? 1 : (int) (urls.size() / 0.75f + 1));
424	        if (urls == null || urls.isEmpty()) {
425	            return newUrlInvokerMap;
426	        }
427	
428	        for (URL url : urls) {
429	            InstanceAddressURL instanceAddressURL = (InstanceAddressURL) url;
430	            if (EMPTY_PROTOCOL.equals(instanceAddressURL.getProtocol())) {
431	                continue;
432	            }
433	            if (!getUrl().getOrDefaultFrameworkModel()
434	                    .getExtensionLoader(Protocol.class)
435	                    .hasExtension(instanceAddressURL.getProtocol())) {
436	
437	                // 4-1 - Unsupported protocol
438	
439	                logger.error(
440	                        PROTOCOL_UNSUPPORTED,
441	                        "protocol extension does not installed",
442	                        "",
443	                        "Unsupported protocol.",
444	                        new IllegalStateException("Unsupported protocol " + instanceAddressURL.getProtocol()
445	                                + " in notified url: "
446	                                + instanceAddressURL + " from registry " + getUrl().getAddress() + " to consumer "
447	                                + NetUtils.getLocalHost() + ", supported protocol: "
448	                                + getUrl().getOrDefaultFrameworkModel()
449	                                        .getExtensionLoader(Protocol.class)
450	                                        .getSupportedExtensions()));
451	
452	                continue;
453	            }
454	
455	            instanceAddressURL.setProviderFirstParams(providerFirstParams);
456	
457	            // Override provider urls if needed
458	            if (enableConfigurationListen) {
459	                instanceAddressURL = overrideWithConfigurator(instanceAddressURL);
460	            }
461	
462	            // filter all the service available (version wildcard, group wildcard, protocol wildcard)
463	            List<ProtocolServiceKey> matchedProtocolServiceKeys =
464	                    getMatchedProtocolServiceKeys(instanceAddressURL, true);
465	            if (CollectionUtils.isEmpty(matchedProtocolServiceKeys)) {
466	                // if preferred protocol is not specified, use the default main protocol
467	                matchedProtocolServiceKeys = getMatchedProtocolServiceKeys(instanceAddressURL, false);
468	            }
469	
470	            // see org.apache.dubbo.common.ProtocolServiceKey.isSameWith
471	            // check if needed to override the consumer url
472	            boolean shouldWrap = matchedProtocolServiceKeys.size() != 1
473	                    || !consumerProtocolServiceKey.isSameWith(matchedProtocolServiceKeys.get(0));
474	
475	            for (ProtocolServiceKey matchedProtocolServiceKey : matchedProtocolServiceKeys) {
476	                ProtocolServiceKeyWithAddress protocolServiceKeyWithAddress =
477	                        new ProtocolServiceKeyWithAddress(matchedProtocolServiceKey, instanceAddressURL.getAddress());
478	                Invoker<T> invoker =
479	                        oldUrlInvokerMap == null ? null : oldUrlInvokerMap.get(protocolServiceKeyWithAddress);
480	                if (invoker == null
481	                        || urlChanged(
482	                                invoker,
483	                                instanceAddressURL,
484	                                matchedProtocolServiceKey)) { // Not in the cache, refer again
485	                    try {
486	                        boolean enabled;
487	                        if (instanceAddressURL.hasParameter(DISABLED_KEY)) {
488	                            enabled = !instanceAddressURL.getParameter(DISABLED_KEY, false);
489	                        } else {
490	                            enabled = instanceAddressURL.getParameter(ENABLED_KEY, true);
491	                        }
492	                        if (enabled) {
493	                            if (shouldWrap) {
494	                                URL newConsumerUrl = ConcurrentHashMapUtils.computeIfAbsent(
495	                                        customizedConsumerUrlMap, matchedProtocolServiceKey, k -> consumerUrl
496	                                                .setProtocol(k.getProtocol())
497	                                                .addParameter(CommonConstants.GROUP_KEY, k.getGroup())
498	                                                .addParameter(CommonConstants.VERSION_KEY, k.getVersion()));
499	                                RpcContext.getServiceContext().setConsumerUrl(newConsumerUrl);
500	                                invoker = new InstanceWrappedInvoker<>(
501	                                        protocol.refer(serviceType, instanceAddressURL),
502	                                        newConsumerUrl,
503	                                        matchedProtocolServiceKey);
504	                            } else {
505	                                invoker = protocol.refer(serviceType, instanceAddressURL);
506	                            }
507	                        }
508	                    } catch (Throwable t) {
509	                        logger.error(
510	                                PROTOCOL_FAILED_REFER_INVOKER,
511	                                "",
512	                                "",
513	                                "Failed to refer invoker for interface:" + serviceType + ",url:(" + instanceAddressURL
514	                                        + ")" + t.getMessage(),
515	                                t);
516	                    }
517	                    if (invoker != null) { // Put new invoker in cache
518	                        newUrlInvokerMap.put(protocolServiceKeyWithAddress, invoker);
519	                    }
520	                } else {
521	                    newUrlInvokerMap.put(protocolServiceKeyWithAddress, invoker);
522	                    oldUrlInvokerMap.remove(protocolServiceKeyWithAddress, invoker);
523	                }
524	            }
525	        }
526	        return newUrlInvokerMap;
527	    }
