529	    private List<ProtocolServiceKey> getMatchedProtocolServiceKeys(
530	            InstanceAddressURL instanceAddressURL, boolean needPreferred) {
531	        int port = instanceAddressURL.getPort();
532	        return instanceAddressURL.getMetadataInfo().getMatchedServiceInfos(consumerProtocolServiceKey).stream()
533	                .filter(serviceInfo -> serviceInfo.getPort() <= 0 || serviceInfo.getPort() == port)
534	                // special filter for extra protocols.
535	                .filter(serviceInfo -> {
536	                    if (StringUtils.isNotEmpty(
537	                            consumerProtocolServiceKey
538	                                    .getProtocol())) { // if consumer side protocol is specified, use all
539	                        // the protocols we got in hand now directly
540	                        return true;
541	                    } else {
542	                        // if consumer side protocol is not specified, choose the preferred or default main protocol
543	                        if (needPreferred) {
544	                            return serviceInfo.getProtocol().equals(serviceInfo.getParameter(PREFERRED_PROTOCOL));
545	                        } else {
546	                            return StringUtils.isEmpty(serviceInfo.getParameter(IS_EXTRA));
547	                        }
548	                    }
549	                })
550	                .map(MetadataInfo.ServiceInfo::getProtocolServiceKey)
551	                .collect(Collectors.toList());
552	    }
