554	    private boolean urlChanged(Invoker<T> invoker, InstanceAddressURL newURL, ProtocolServiceKey protocolServiceKey) {
555	        InstanceAddressURL oldURL = (InstanceAddressURL) invoker.getUrl();
556	
557	        if (!newURL.getInstance().equals(oldURL.getInstance())) {
558	            return true;
559	        }
560	
561	        if (oldURL instanceof OverrideInstanceAddressURL || newURL instanceof OverrideInstanceAddressURL) {
562	            if (!(oldURL instanceof OverrideInstanceAddressURL && newURL instanceof OverrideInstanceAddressURL)) {
563	                // sub-class changed
564	                return true;
565	            } else {
566	                if (!((OverrideInstanceAddressURL) oldURL)
567	                        .getOverrideParams()
568	                        .equals(((OverrideInstanceAddressURL) newURL).getOverrideParams())) {
569	                    return true;
570	                }
571	            }
572	        }
573	
574	        MetadataInfo.ServiceInfo oldServiceInfo =
575	                oldURL.getMetadataInfo().getValidServiceInfo(protocolServiceKey.toString());
576	        if (null == oldServiceInfo) {
577	            return false;
578	        }
579	
580	        return !oldServiceInfo.equals(newURL.getMetadataInfo().getValidServiceInfo(protocolServiceKey.toString()));
581	    }
