583	    private List<Invoker<T>> toMergeInvokerList(List<Invoker<T>> invokers) {
584	        List<Invoker<T>> mergedInvokers = new ArrayList<>();
585	        Map<String, List<Invoker<T>>> groupMap = new HashMap<>();
586	        for (Invoker<T> invoker : invokers) {
587	            String group = invoker.getUrl().getGroup("");
588	            groupMap.computeIfAbsent(group, k -> new ArrayList<>());
589	            groupMap.get(group).add(invoker);
590	        }
591	
592	        if (groupMap.size() == 1) {
593	            mergedInvokers.addAll(groupMap.values().iterator().next());
594	        } else if (groupMap.size() > 1) {
595	            for (List<Invoker<T>> groupList : groupMap.values()) {
596	                StaticDirectory<T> staticDirectory = new StaticDirectory<>(groupList);
597	                staticDirectory.buildRouterChain();
598	                mergedInvokers.add(cluster.join(staticDirectory, false));
599	            }
600	        } else {
601	            mergedInvokers = invokers;
602	        }
603	        return mergedInvokers;
604	    }
