607	     * Close all invokers
608	     */
609	    @Override
610	    protected void destroyAllInvokers() {
611	        Map<ProtocolServiceKeyWithAddress, Invoker<T>> localUrlInvokerMap = this.urlInvokerMap; // local reference
612	        if (localUrlInvokerMap != null) {
613	            for (Invoker<T> invoker : new ArrayList<>(localUrlInvokerMap.values())) {
614	                try {
615	                    invoker.destroy();
616	                } catch (Throwable t) {
617	                    logger.warn(
618	                            PROTOCOL_FAILED_DESTROY_INVOKER,
619	                            "",
620	                            "",
621	                            "Failed to destroy service " + serviceKey + " to provider " + invoker.getUrl(),
622	                            t);
623	                }
624	            }
625	            localUrlInvokerMap.clear();
626	        }
627	
628	        this.urlInvokerMap = null;
629	        this.destroyInvokers();
630	    }
