646	    /**
647	     * Check whether the invoker in the cache needs to be destroyed
648	     * If set attribute of url: refer.autodestroy=false, the invokers will only increase without decreasing,there may be a refer leak
649	     *
650	     * @param oldUrlInvokerMap
651	     * @param newUrlInvokerMap
652	     */
653	    private void destroyUnusedInvokers(
654	            Map<ProtocolServiceKeyWithAddress, Invoker<T>> oldUrlInvokerMap,
655	            Map<ProtocolServiceKeyWithAddress, Invoker<T>> newUrlInvokerMap) {
656	        if (newUrlInvokerMap == null || newUrlInvokerMap.size() == 0) {
657	            destroyAllInvokers();
658	            return;
659	        }
660	
661	        if (oldUrlInvokerMap == null || oldUrlInvokerMap.size() == 0) {
662	            return;
663	        }
664	
665	        for (Map.Entry<ProtocolServiceKeyWithAddress, Invoker<T>> entry : oldUrlInvokerMap.entrySet()) {
666	            Invoker<T> invoker = entry.getValue();
667	            if (invoker != null) {
668	                try {
669	                    invoker.destroy();
670	                    if (logger.isDebugEnabled()) {
671	                        logger.debug("destroy invoker[" + invoker.getUrl() + "] success. ");
672	                    }
673	                } catch (Exception e) {
674	                    logger.warn(
675	                            PROTOCOL_FAILED_DESTROY_INVOKER,
676	                            "",
677	                            "",
678	                            "destroy invoker[" + invoker.getUrl() + "]failed." + e.getMessage(),
679	                            e);
680	                }
681	            }
682	        }
683	        logger.info(oldUrlInvokerMap.size() + " deprecated invokers deleted.");
684	    }
