785	    public static final class InstanceWrappedInvoker<T> implements Invoker<T> {
786	        private final Invoker<T> originInvoker;
787	        private final URL newConsumerUrl;
788	        private final ProtocolServiceKey protocolServiceKey;
789	
790	        public InstanceWrappedInvoker(
791	                Invoker<T> originInvoker, URL newConsumerUrl, ProtocolServiceKey protocolServiceKey) {
792	            this.originInvoker = originInvoker;
793	            this.newConsumerUrl = newConsumerUrl;
794	            this.protocolServiceKey = protocolServiceKey;
795	        }
796	
797	        @Override
798	        public Class<T> getInterface() {
799	            return originInvoker.getInterface();
800	        }
801	
802	        @Override
803	        public Result invoke(Invocation invocation) throws RpcException {
804	            // override consumer url with real protocol service key
805	            RpcContext.getServiceContext().setConsumerUrl(newConsumerUrl);
806	            // recreate invocation due to the protocol service key changed
807	            RpcInvocation copiedInvocation = new RpcInvocation(
808	                    invocation.getTargetServiceUniqueName(),
809	                    invocation.getServiceModel(),
810	                    invocation.getMethodName(),
811	                    invocation.getServiceName(),
812	                    protocolServiceKey.toString(),
813	                    invocation.getParameterTypes(),
814	                    invocation.getArguments(),
815	                    invocation.getObjectAttachments(),
816	                    invocation.getInvoker(),
817	                    invocation.getAttributes(),
818	                    invocation instanceof RpcInvocation ? ((RpcInvocation) invocation).getInvokeMode() : null);
819	            copiedInvocation.setObjectAttachment(CommonConstants.GROUP_KEY, protocolServiceKey.getGroup());
820	            copiedInvocation.setObjectAttachment(CommonConstants.VERSION_KEY, protocolServiceKey.getVersion());
821	            // When there are multiple MethodDescriptors with the same method name, the return type will be wrong
822	            // same with org.apache.dubbo.rpc.stub.StubInvocationUtil.call
823	            // fix https://github.com/apache/dubbo/issues/13931
824	            if (invocation instanceof RpcInvocation) {
825	                copiedInvocation.setReturnType(((RpcInvocation) invocation).getReturnType());
826	            }
827	            return originInvoker.invoke(copiedInvocation);
828	        }
829	
830	        @Override
831	        public URL getUrl() {
832	            RpcContext.getServiceContext().setConsumerUrl(newConsumerUrl);
833	            return originInvoker.getUrl();
834	        }
835	
836	        @Override
837	        public boolean isAvailable() {
838	            RpcContext.getServiceContext().setConsumerUrl(newConsumerUrl);
839	            return originInvoker.isAvailable();
840	        }
841	
842	        @Override
843	        public void destroy() {
844	            RpcContext.getServiceContext().setConsumerUrl(newConsumerUrl);
845	            originInvoker.destroy();
846	        }
847	    }
