849	    @Override
850	    public String toString() {
851	        return "ServiceDiscoveryRegistryDirectory(" + "registry: "
852	                + getUrl().getAddress() + ", subscribed key: "
853	                + (serviceListener == null || CollectionUtils.isEmpty(serviceListener.getServiceNames())
854	                        ? getConsumerUrl().getServiceKey()
855	                        : serviceListener.getServiceNames().toString())
