108	
109	    /**
110	     * The initial value is null and the midway may be assigned to null, please use the local variable reference
111	     * override rules
112	     * Priority: override>-D>consumer>provider
113	     * Rule one: for a certain provider <ip:port,timeout=100>
114	     * Rule two: for all providers <* ,timeout=5000>
115	     */
116	    protected volatile List<Configurator> configurators;
