128	    public DynamicDirectory(Class<T> serviceType, URL url) {
129	        super(url, true);
130	
131	        ModuleModel moduleModel = url.getOrDefaultModuleModel();
132	
133	        this.cluster = moduleModel.getExtensionLoader(Cluster.class).getAdaptiveExtension();
134	        this.routerFactory = moduleModel.getExtensionLoader(RouterFactory.class).getAdaptiveExtension();
135	
136	        if (serviceType == null) {
137	            throw new IllegalArgumentException("service type is null.");
138	        }
139	
140	        if (StringUtils.isEmpty(url.getServiceKey())) {
141	            throw new IllegalArgumentException("registry serviceKey is null.");
142	        }
143	
144	        this.shouldRegister = !ANY_VALUE.equals(url.getServiceInterface()) && url.getParameter(REGISTER_KEY, true);
145	        this.shouldSimplified = url.getParameter(SIMPLIFIED_KEY, false);
146	
147	        this.serviceType = serviceType;
148	        this.serviceKey = super.getConsumerUrl().getServiceKey();
149	
150	        this.directoryUrl = consumerUrl;
151	        String group = directoryUrl.getGroup("");
152	        this.multiGroup = group != null && (ANY_VALUE.equals(group) || group.contains(","));
