194	    @Override
195	    public List<Invoker<T>> doList(
196	            SingleRouterChain<T> singleRouterChain, BitList<Invoker<T>> invokers, Invocation invocation) {
197	        if (forbidden && shouldFailFast) {
198	            // 1. No service provider 2. Service providers are disabled
199	            throw new RpcException(
200	                    RpcException.FORBIDDEN_EXCEPTION,
201	                    "No provider available from registry " + this
202	                            + " for service " + getConsumerUrl().getServiceKey() + " on consumer "
203	                            + NetUtils.getLocalHost()
204	                            + " use dubbo version " + Version.getVersion()
205	                            + ", please check status of providers(disabled, not registered or in blocklist).");
206	        }
207	
208	        if (multiGroup) {
209	            return this.getInvokers();
210	        }
211	
212	        try {
213	            // Get invokers from cache, only runtime routers will be executed.
214	            List<Invoker<T>> result = singleRouterChain.route(getConsumerUrl(), invokers, invocation);
215	            return result == null ? BitList.emptyList() : result;
216	        } catch (Throwable t) {
217	            // 2-1 - Failed to execute routing.
218	            logger.error(
219	                    CLUSTER_FAILED_SITE_SELECTION,
220	                    "",
221	                    "",
222	                    "Failed to execute router: " + getUrl() + ", cause: " + t.getMessage(),
223	                    t);
224	
225	            return BitList.emptyList();
226	        }
227	    }
