294	    @Override
295	    public boolean isAvailable() {
296	        if (isDestroyed() || this.forbidden) {
297	            return false;
298	        }
299	        for (Invoker<T> validInvoker : getValidInvokers()) {
300	            if (validInvoker.isAvailable()) {
301	                return true;
302	            } else {
303	                addInvalidateInvoker(validInvoker);
304	            }
305	        }
306	        return false;
307	    }
308	
309	    @Override
310	    public void destroy() {
311	        if (isDestroyed()) {
312	            return;
313	        }
314	
315	        // unregister.
316	        try {
317	            if (getRegisteredConsumerUrl() != null && registry != null && registry.isAvailable()) {
318	                registry.unregister(getRegisteredConsumerUrl());
319	            }
320	        } catch (Throwable t) {
321	            // 1-8: Failed to unregister / unsubscribe url on destroy.
322	            logger.warn(
323	                    REGISTRY_FAILED_DESTROY_UNREGISTER_URL,
324	                    "",
325	                    "",
326	                    "unexpected error when unregister service " + serviceKey + " from registry: " + registry.getUrl(),
327	                    t);
328	        }
329	
330	        // unsubscribe.
331	        try {
332	            if (getSubscribeUrl() != null && registry != null && registry.isAvailable()) {
333	                registry.unsubscribe(getSubscribeUrl(), this);
334	            }
335	        } catch (Throwable t) {
336	            // 1-8: Failed to unregister / unsubscribe url on destroy.
337	            logger.warn(
338	                    REGISTRY_FAILED_DESTROY_UNREGISTER_URL,
339	                    "",
340	                    "",
341	                    "unexpected error when unsubscribe service " + serviceKey + " from registry: " + registry.getUrl(),
342	                    t);
343	        }
344	
345	        ExtensionLoader<AddressListener> addressListenerExtensionLoader =
346	                getUrl().getOrDefaultModuleModel().getExtensionLoader(AddressListener.class);
347	        List<AddressListener> supportedListeners =
348	                addressListenerExtensionLoader.getActivateExtension(getUrl(), (String[]) null);
349	        if (CollectionUtils.isNotEmpty(supportedListeners)) {
350	            for (AddressListener addressListener : supportedListeners) {
351	                addressListener.destroy(getConsumerUrl(), this);
352	            }
353	        }
354	
355	        synchronized (this) {
356	            try {
357	                destroyAllInvokers();
358	            } catch (Throwable t) {
359	                // 1-15 - Failed to destroy service.
360	                logger.warn(REGISTRY_FAILED_DESTROY_SERVICE, "", "", "Failed to destroy service " + serviceKey, t);
361	            }
362	            routerChain.destroy();
363	            invokersChangedListener = null;
364	            serviceListener = null;
365	
366	            super.destroy(); // must be executed after unsubscribing
367	        }
368	    }
369	
370	    @Override
371	    public void discordAddresses() {
372	        try {
373	            destroyAllInvokers();
374	        } catch (Throwable t) {
375	            // 1-15 - Failed to destroy service.
376	            logger.warn(REGISTRY_FAILED_DESTROY_SERVICE, "", "", "Failed to destroy service " + serviceKey, t);
377	        }
378	    }
379	
380	    public synchronized void setInvokersChangedListener(InvokersChangedListener listener) {
381	        this.invokersChangedListener = listener;
382	        if (invokersChangedListener != null && invokersChanged) {
383	            invokersChangedListener.onChange();
384	        }
385	    }
386	
387	    protected synchronized void invokersChanged() {
388	        refreshInvoker();
389	        invokersChanged = true;
390	        if (invokersChangedListener != null) {
391	            invokersChangedListener.onChange();
392	            invokersChanged = false;
393	        }
394	    }
395	
396	    @Override
397	    public boolean isNotificationReceived() {
398	        return invokersChanged;
399	    }
400	
401	    protected abstract void destroyAllInvokers();
402	
403	    protected abstract void refreshOverrideAndInvoker(List<URL> urls);
404	}
