55	import static org.apache.dubbo.rpc.Constants.H2_SETTINGS_IGNORE_1_0_0_KEY;
56	import static org.apache.dubbo.rpc.Constants.H2_SETTINGS_OPENAPI_ENABLED;
57	import static org.apache.dubbo.rpc.Constants.H2_SETTINGS_RESOLVE_FALLBACK_TO_DEFAULT_KEY;
58	import static org.apache.dubbo.rpc.Constants.H2_SETTINGS_REST_ENABLED;
59	import static org.apache.dubbo.rpc.Constants.H2_SETTINGS_SUPPORT_NO_LOWER_HEADER_KEY;
60	import static org.apache.dubbo.rpc.Constants.H2_SETTINGS_VERBOSE_ENABLED;
61	
62	public class TripleProtocol extends AbstractProtocol {
63	
64	    private final PathResolver pathResolver;
65	    private final RequestMappingRegistry mappingRegistry;
66	    private final TriBuiltinService triBuiltinService;
67	    private final String acceptEncodings;
68	
69	    public static boolean CONVERT_NO_LOWER_HEADER = true;
70	    public static boolean IGNORE_1_0_0_VERSION = false;
71	    public static boolean RESOLVE_FALLBACK_TO_DEFAULT = true;
72	    public static boolean VERBOSE_ENABLED = false;
73	    public static boolean REST_ENABLED = true;
74	    public static boolean OPENAPI_ENABLED = false;
75	
76	    public TripleProtocol(FrameworkModel frameworkModel) {
77	        this.frameworkModel = frameworkModel;
78	        triBuiltinService = new TriBuiltinService(frameworkModel);
79	        pathResolver = frameworkModel.getDefaultExtension(PathResolver.class);
80	        mappingRegistry = frameworkModel.getOrRegisterBean(DefaultRequestMappingRegistry.class);
81	        acceptEncodings = String.join(",", frameworkModel.getSupportedExtensions(DeCompressor.class));
82	
83	        // init env settings
84	        Configuration conf = ConfigurationUtils.getEnvConfiguration(ApplicationModel.defaultModel());
85	        CONVERT_NO_LOWER_HEADER = conf.getBoolean(H2_SETTINGS_SUPPORT_NO_LOWER_HEADER_KEY, true);
86	        IGNORE_1_0_0_VERSION = conf.getBoolean(H2_SETTINGS_IGNORE_1_0_0_KEY, false);
87	        RESOLVE_FALLBACK_TO_DEFAULT = conf.getBoolean(H2_SETTINGS_RESOLVE_FALLBACK_TO_DEFAULT_KEY, true);
88	
89	        // init global settings
90	        Configuration globalConf = ConfigurationUtils.getGlobalConfiguration(frameworkModel.defaultApplication());
91	        VERBOSE_ENABLED = globalConf.getBoolean(H2_SETTINGS_VERBOSE_ENABLED, false);
92	        REST_ENABLED = globalConf.getBoolean(H2_SETTINGS_REST_ENABLED, true);
93	        OPENAPI_ENABLED = globalConf.getBoolean(H2_SETTINGS_OPENAPI_ENABLED, false);
94	
95	        ServletExchanger.init(globalConf);
96	        Http3Exchanger.init(globalConf);
97	
98	        this.frameworkModel.getBeanFactory().registerBean(new TripleGracefulShutdown(this));
99	    }
100	
101	    @Override
102	    public int getDefaultPort() {
103	        return 50051;
104	    }
105	
106	    @Override
107	    public <T> Exporter<T> export(Invoker<T> invoker) throws RpcException {
108	        URL url = invoker.getUrl();
109	        String key = serviceKey(url);
110	
111	        // create exporter
112	        AbstractExporter<T> exporter = new AbstractExporter<T>(invoker) {
113	            @Override
114	            public void afterUnExport() {
115	                // unregister grpc request mapping
116	                pathResolver.unregister(invoker);
117	
118	                // unregister rest request mapping
119	                if (REST_ENABLED) {
120	                    mappingRegistry.unregister(invoker);
121	                }
122	
123	                // set service status to NOT_SERVING
124	                setServiceStatus(url, false);
125	
126	                exporterMap.remove(key);
127	            }
128	        };
129	        exporterMap.put(key, exporter);
130	
131	        // add invoker
132	        invokers.add(invoker);
133	
134	        // register grpc path mapping
135	        pathResolver.register(invoker);
136	
137	        // register rest request mapping
138	        if (REST_ENABLED) {
139	            mappingRegistry.register(invoker);
140	        }
141	
142	        // set service status to SERVING
143	        setServiceStatus(url, true);
144	
145	        // init server executor
146	        ExecutorRepository.getInstance(url.getOrDefaultApplicationModel())
147	                .createExecutorIfAbsent(ExecutorUtil.setThreadName(url, SERVER_THREAD_POOL_NAME));
148	
149	        // bind server port
150	        bindServerPort(url);
151	
152	        // optimize serialization
153	        optimizeSerialization(url);
154	
155	        return exporter;
156	    }
157	
158	    private void setServiceStatus(URL url, boolean serving) {
159	        if (triBuiltinService.enable()) {
160	            ServingStatus status = serving ? ServingStatus.SERVING : ServingStatus.NOT_SERVING;
161	            triBuiltinService.getHealthStatusManager().setStatus(url.getServiceKey(), status);
162	            triBuiltinService.getHealthStatusManager().setStatus(url.getServiceInterface(), status);
163	        }
164	    }
165	
166	    private void bindServerPort(URL url) {
167	        boolean bindPort = true;
168	
169	        if (ServletExchanger.isEnabled()) {
170	            int port = url.getParameter(Constants.BIND_PORT_KEY, url.getPort());
171	            Integer serverPort = ServletExchanger.getServerPort();
172	            if (serverPort == null) {
173	                if (NetUtils.isPortInUsed(port)) {
174	                    bindPort = false;
175	                }
176	            } else if (serverPort == port) {
177	                bindPort = false;
178	            }
179	            ServletExchanger.bind(url);
180	        }
181	
182	        if (bindPort) {
183	            String addr = url.getAddress();
184	            ConcurrentHashMapUtils.computeIfAbsent(serverMap, addr, k -> {
185	                RemotingServer remotingServer = PortUnificationExchanger.bind(url, new DefaultPuHandler());
186	                return new DefaultProtocolServer(remotingServer);
187	            });
188	        }
189	
190	        Http3Exchanger.bind(url);
191	    }
192	
193	    @Override
194	    public <T> Invoker<T> refer(Class<T> type, URL url) throws RpcException {
195	        optimizeSerialization(url);
196	        ExecutorService streamExecutor = getOrCreateStreamExecutor(url.getOrDefaultApplicationModel(), url);
197	        AbstractConnectionClient connectionClient = Http3Exchanger.isEnabled(url)
198	                ? Http3Exchanger.connect(url)
199	                : PortUnificationExchanger.connect(url, new DefaultPuHandler());
200	        TripleInvoker<T> invoker =
201	                new TripleInvoker<>(type, url, acceptEncodings, connectionClient, invokers, streamExecutor);
202	        invokers.add(invoker);
203	        return invoker;
204	    }
205	
206	    private ExecutorService getOrCreateStreamExecutor(ApplicationModel applicationModel, URL url) {
207	        url = url.addParameter(THREAD_NAME_KEY, CLIENT_THREAD_POOL_NAME)
208	                .addParameterIfAbsent(THREADPOOL_KEY, DEFAULT_CLIENT_THREADPOOL);
209	        ExecutorService executor =
210	                ExecutorRepository.getInstance(applicationModel).createExecutorIfAbsent(url);
211	        Objects.requireNonNull(executor, String.format("No available executor found in %s", url));
212	        return executor;
213	    }
214	
215	    @Override
216	    protected <T> Invoker<T> protocolBindingRefer(Class<T> type, URL url) throws RpcException {
217	        return null;
218	    }
219	
220	    @Override
221	    public void destroy() {
222	        if (logger.isInfoEnabled()) {
223	            logger.info("Destroying protocol [{}] ...", getClass().getSimpleName());
224	        }
225	        PortUnificationExchanger.close();
226	        Http3Exchanger.close();
227	        pathResolver.destroy();
228	        if (REST_ENABLED) {
229	            mappingRegistry.destroy();
230	        }
231	        super.destroy();
232	    }
233	}
