80	@Activate
81	public class TripleHttp2Protocol extends AbstractWireProtocol implements ScopeModelAware {
82	
83	    public static final Http2FrameLogger CLIENT_LOGGER = new Http2FrameLogger(LogLevel.DEBUG, "H2_CLIENT");
84	
85	    public static final Http2FrameLogger SERVER_LOGGER = new Http2FrameLogger(LogLevel.DEBUG, "H2_SERVER");
86	
87	    private FrameworkModel frameworkModel;
88	
89	    public TripleHttp2Protocol() {
90	        super(new TripleProtocolDetector());
91	    }
92	
93	    @Override
94	    public void setFrameworkModel(FrameworkModel frameworkModel) {
95	        this.frameworkModel = frameworkModel;
96	    }
97	
98	    @Override
99	    public void close() {
100	        super.close();
101	    }
102	
103	    @Override
104	    public void configClientPipeline(URL url, ChannelOperator operator, ContextOperator contextOperator) {
105	        TripleConfig tripleConfig = ConfigManager.getProtocolOrDefault(url).getTripleOrDefault();
106	        Http2Connection connection = createHttp2ClientConnection(tripleConfig);
107	        Http2FrameCodec codec = TripleHttp2FrameCodecBuilder.fromConnection(connection)
108	                .gracefulShutdownTimeoutMillis(10000)
109	                .initialSettings(new Http2Settings()
110	                        .headerTableSize(tripleConfig.getHeaderTableSizeOrDefault())
111	                        .pushEnabled(tripleConfig.getEnablePushOrDefault())
112	                        .maxConcurrentStreams(tripleConfig.getMaxConcurrentStreamsOrDefault())
113	                        .initialWindowSize(tripleConfig.getInitialWindowSizeOrDefault())
114	                        .maxFrameSize(tripleConfig.getMaxFrameSizeOrDefault())
115	                        .maxHeaderListSize(tripleConfig.getMaxHeaderListSizeOrDefault()))
116	                .frameLogger(CLIENT_LOGGER)
117	                .validateHeaders(false)
118	                .build();
119	        List<ChannelHandler> handlers = new ArrayList<>();
120	        handlers.add(new ChannelHandlerPretender(codec));
121	        handlers.add(new ChannelHandlerPretender(new Http2MultiplexHandler(new ChannelDuplexHandler())));
122	        handlers.add(new ChannelHandlerPretender(new TriplePingPongHandler(UrlUtils.getCloseTimeout(url))));
123	        handlers.add(new ChannelHandlerPretender(new TripleGoAwayHandler()));
124	        handlers.add(new ChannelHandlerPretender(new TripleTailHandler()));
125	        operator.configChannelHandler(handlers);
126	    }
127	
128	    private Http2Connection createHttp2ClientConnection(TripleConfig tripleConfig) {
129	        Http2Connection connection = new DefaultHttp2Connection(false);
130	        float windowUpdateRatio = tripleConfig.getWindowUpdateRatioOrDefault();
131	        connection.local().flowController(TripleHttp2LocalFlowController.newController(connection, windowUpdateRatio));
132	        connection.remote().flowController(TripleHttp2RemoteFlowController.newController(connection));
133	        return connection;
134	    }
135	
136	    @Override
137	    public void configServerProtocolHandler(URL url, ChannelOperator operator) {
138	        String httpVersion = operator.detectResult().getAttribute(TripleProtocolDetector.HTTP_VERSION);
139	        List<ChannelHandler> channelHandlerPretenders = new ArrayList<>();
140	        try {
141	            // h1
142	            if (HttpVersion.HTTP1.getVersion().equals(httpVersion)) {
143	                configurerHttp1Handlers(url, channelHandlerPretenders);
144	                return;
145	            }
146	
147	            // h2
148	            if (HttpVersion.HTTP2.getVersion().equals(httpVersion)) {
149	                configurerHttp2Handlers(url, channelHandlerPretenders);
150	            }
151	        } finally {
152	            operator.configChannelHandler(channelHandlerPretenders);
153	        }
154	    }
155	
156	    @SuppressWarnings("deprecation")
157	    private void configurerHttp1Handlers(URL url, List<ChannelHandler> handlers) {
158	        TripleConfig tripleConfig = ConfigManager.getProtocolOrDefault(url).getTripleOrDefault();
159	        HttpServerCodec sourceCodec = new HttpServerCodec(
160	                tripleConfig.getMaxInitialLineLengthOrDefault(),
161	                tripleConfig.getMaxHeaderSizeOrDefault(),
162	                tripleConfig.getMaxChunkSizeOrDefault(),
163	                false,
164	                tripleConfig.getInitialBufferSizeOrDefault());
165	        handlers.add(new ChannelHandlerPretender(sourceCodec));
166	        // Triple protocol http1 upgrade support
167	        handlers.add(new ChannelHandlerPretender(new HttpServerUpgradeHandler(
168	                sourceCodec,
169	                protocol -> {
170	                    if (AsciiString.contentEquals(Http2CodecUtil.HTTP_UPGRADE_PROTOCOL_NAME, protocol)) {
171	                        NettyHttp2SettingsHandler nettyHttp2SettingsHandler = new NettyHttp2SettingsHandler();
172	                        Http2Connection http2ServerConnection = createHttp2ServerConnection(tripleConfig);
173	                        Http2FrameCodec http2FrameCodec = buildHttp2FrameCodec(http2ServerConnection, tripleConfig);
174	                        return new Http2ServerUpgradeCodec(
175	                                http2FrameCodec,
176	                                nettyHttp2SettingsHandler,
177	                                new HttpWriteQueueHandler(),
178	                                new FlushConsolidationHandler(64, true),
179	                                new TripleServerConnectionHandler(),
180	                                buildHttp2MultiplexHandler(
181	                                        nettyHttp2SettingsHandler, url, tripleConfig, http2ServerConnection),
182	                                new TripleTailHandler());
183	                    } else if (AsciiString.contentEquals(HttpHeaderValues.WEBSOCKET, protocol)) {
184	                        return new WebSocketServerUpgradeCodec(
185	                                Arrays.asList(
186	                                        HttpObjectAggregator.class,
187	                                        NettyHttp1Codec.class,
188	                                        NettyHttp1ConnectionHandler.class),
189	                                new WebSocketServerCompressionHandler(),
190	                                new HttpWriteQueueHandler(),
191	                                new WebSocketProtocolSelectorHandler(
192	                                        url,
193	                                        frameworkModel,
194	                                        tripleConfig,
195	                                        DefaultWebSocketServerTransportListenerFactory.INSTANCE),
196	                                buildWebSocketServerProtocolHandler(tripleConfig),
197	                                new WebSocketFrameCodec());
198	                    }
199	                    // Not upgrade request
200	                    return null;
201	                },
202	                Integer.MAX_VALUE)));
203	        // If the upgrade was successful, remove the message from the output list
204	        // so that it's not propagated to the next handler. This request will
205	        // be propagated as a user event instead.
206	        handlers.add(new ChannelHandlerPretender(new HttpObjectAggregator(tripleConfig.getMaxBodySizeOrDefault())));
207	        handlers.add(new ChannelHandlerPretender(new NettyHttp1Codec()));
208	        handlers.add(new ChannelHandlerPretender(new NettyHttp1ConnectionHandler(
209	                url, frameworkModel, tripleConfig, DefaultHttp11ServerTransportListenerFactory.INSTANCE)));
210	    }
211	
212	    private Http2MultiplexHandler buildHttp2MultiplexHandler(
213	            NettyHttp2SettingsHandler nettyHttp2SettingsHandler,
214	            URL url,
215	            TripleConfig tripleConfig,
216	            Http2Connection http2Connection) {
217	        return new Http2MultiplexHandler(new ChannelInitializer<Http2StreamChannel>() {
218	            @Override
219	            protected void initChannel(Http2StreamChannel ch) {
220	                // Disable Netty's automatic stream flow control to enable manual flow control
221	                // This prevents Netty from automatically sending WINDOW_UPDATE frames
222	                // Application code will call consumeBytes() to trigger WINDOW_UPDATE when ready
223	                ch.config().setOption(Http2StreamChannelOption.AUTO_STREAM_FLOW_CONTROL, false);
224	                ChannelPipeline p = ch.pipeline();
225	                p.addLast(new NettyHttp2FrameCodec(nettyHttp2SettingsHandler));
226	                p.addLast(new NettyHttp2ProtocolSelectorHandler(
227	                        url,
228	                        frameworkModel,
229	                        tripleConfig,
230	                        GenericHttp2ServerTransportListenerFactory.INSTANCE,
231	                        http2Connection));
232	            }
233	        });
234	    }
235	
236	    private void configurerHttp2Handlers(URL url, List<ChannelHandler> handlers) {
237	        NettyHttp2SettingsHandler nettyHttp2SettingsHandler = new NettyHttp2SettingsHandler();
238	        TripleConfig tripleConfig = ConfigManager.getProtocolOrDefault(url).getTripleOrDefault();
239	        Http2Connection connection = createHttp2ServerConnection(tripleConfig);
240	        Http2FrameCodec codec = buildHttp2FrameCodec(connection, tripleConfig);
241	        Http2MultiplexHandler handler =
242	                buildHttp2MultiplexHandler(nettyHttp2SettingsHandler, url, tripleConfig, connection);
243	        handlers.add(new ChannelHandlerPretender(new HttpWriteQueueHandler()));
244	        handlers.add(new ChannelHandlerPretender(codec));
245	        handlers.add(new ChannelHandlerPretender(nettyHttp2SettingsHandler));
246	        handlers.add(new ChannelHandlerPretender(new FlushConsolidationHandler(64, true)));
247	        handlers.add(new ChannelHandlerPretender(new TripleServerConnectionHandler()));
248	        handlers.add(new ChannelHandlerPretender(handler));
249	        handlers.add(new ChannelHandlerPretender(new TripleTailHandler()));
250	    }
251	
252	    private Http2FrameCodec buildHttp2FrameCodec(Http2Connection connection, TripleConfig tripleConfig) {
253	        return TripleHttp2FrameCodecBuilder.fromConnection(connection)
254	                .gracefulShutdownTimeoutMillis(10000)
255	                .initialSettings(new Http2Settings()
256	                        .headerTableSize(tripleConfig.getHeaderTableSizeOrDefault())
257	                        .maxConcurrentStreams(tripleConfig.getMaxConcurrentStreamsOrDefault())
258	                        .initialWindowSize(tripleConfig.getInitialWindowSizeOrDefault())
259	                        .maxFrameSize(tripleConfig.getMaxFrameSizeOrDefault())
260	                        .maxHeaderListSize(tripleConfig.getMaxHeaderListSizeOrDefault()))
261	                .frameLogger(SERVER_LOGGER)
262	                .validateHeaders(false)
263	                .build();
264	    }
265	
266	    private Http2Connection createHttp2ServerConnection(TripleConfig tripleConfig) {
267	        Http2Connection connection = new DefaultHttp2Connection(true);
268	        float windowUpdateRatio = tripleConfig.getWindowUpdateRatioOrDefault();
269	        connection.local().flowController(TripleHttp2LocalFlowController.newController(connection, windowUpdateRatio));
270	        connection.remote().flowController(TripleHttp2RemoteFlowController.newController(connection));
271	        return connection;
272	    }
273	
274	    private WebSocketServerProtocolHandler buildWebSocketServerProtocolHandler(TripleConfig tripleConfig) {
275	        return new WebSocketServerProtocolHandler(WebSocketServerProtocolConfig.newBuilder()
276	                .checkStartsWith(true)
277	                .handleCloseFrames(false)
278	                .decoderConfig(WebSocketDecoderConfig.newBuilder()
279	                        .maxFramePayloadLength(tripleConfig.getMaxBodySizeOrDefault())
280	                        .build())
281	                .build());
282	    }
283	}
