157	    private void configurerHttp1Handlers(URL url, List<ChannelHandler> handlers) {
158	        TripleConfig tripleConfig = ConfigManager.getProtocolOrDefault(url).getTripleOrDefault();
159	        HttpServerCodec sourceCodec = new HttpServerCodec(
160	                tripleConfig.getMaxInitialLineLengthOrDefault(),
161	                tripleConfig.getMaxHeaderSizeOrDefault(),
162	                tripleConfig.getMaxChunkSizeOrDefault(),
163	                false,
164	                tripleConfig.getInitialBufferSizeOrDefault());
165	        handlers.add(new ChannelHandlerPretender(sourceCodec));
166	        // Triple protocol http1 upgrade support
167	        handlers.add(new ChannelHandlerPretender(new HttpServerUpgradeHandler(
168	                sourceCodec,
169	                protocol -> {
170	                    if (AsciiString.contentEquals(Http2CodecUtil.HTTP_UPGRADE_PROTOCOL_NAME, protocol)) {
171	                        NettyHttp2SettingsHandler nettyHttp2SettingsHandler = new NettyHttp2SettingsHandler();
172	                        Http2Connection http2ServerConnection = createHttp2ServerConnection(tripleConfig);
173	                        Http2FrameCodec http2FrameCodec = buildHttp2FrameCodec(http2ServerConnection, tripleConfig);
174	                        return new Http2ServerUpgradeCodec(
175	                                http2FrameCodec,
176	                                nettyHttp2SettingsHandler,
177	                                new HttpWriteQueueHandler(),
178	                                new FlushConsolidationHandler(64, true),
179	                                new TripleServerConnectionHandler(),
180	                                buildHttp2MultiplexHandler(
181	                                        nettyHttp2SettingsHandler, url, tripleConfig, http2ServerConnection),
182	                                new TripleTailHandler());
183	                    } else if (AsciiString.contentEquals(HttpHeaderValues.WEBSOCKET, protocol)) {
184	                        return new WebSocketServerUpgradeCodec(
185	                                Arrays.asList(
186	                                        HttpObjectAggregator.class,
187	                                        NettyHttp1Codec.class,
188	                                        NettyHttp1ConnectionHandler.class),
189	                                new WebSocketServerCompressionHandler(),
190	                                new HttpWriteQueueHandler(),
191	                                new WebSocketProtocolSelectorHandler(
192	                                        url,
193	                                        frameworkModel,
194	                                        tripleConfig,
195	                                        DefaultWebSocketServerTransportListenerFactory.INSTANCE),
196	                                buildWebSocketServerProtocolHandler(tripleConfig),
197	                                new WebSocketFrameCodec());
198	                    }
199	                    // Not upgrade request
200	                    return null;
201	                },
202	                Integer.MAX_VALUE)));
203	        // If the upgrade was successful, remove the message from the output list
204	        // so that it's not propagated to the next handler. This request will
205	        // be propagated as a user event instead.
206	        handlers.add(new ChannelHandlerPretender(new HttpObjectAggregator(tripleConfig.getMaxBodySizeOrDefault())));
207	        handlers.add(new ChannelHandlerPretender(new NettyHttp1Codec()));
208	        handlers.add(new ChannelHandlerPretender(new NettyHttp1ConnectionHandler(
209	                url, frameworkModel, tripleConfig, DefaultHttp11ServerTransportListenerFactory.INSTANCE)));
210	    }
