212	    private Http2MultiplexHandler buildHttp2MultiplexHandler(
213	            NettyHttp2SettingsHandler nettyHttp2SettingsHandler,
214	            URL url,
215	            TripleConfig tripleConfig,
216	            Http2Connection http2Connection) {
217	        return new Http2MultiplexHandler(new ChannelInitializer<Http2StreamChannel>() {
218	            @Override
219	            protected void initChannel(Http2StreamChannel ch) {
220	                // Disable Netty's automatic stream flow control to enable manual flow control
221	                // This prevents Netty from automatically sending WINDOW_UPDATE frames
222	                // Application code will call consumeBytes() to trigger WINDOW_UPDATE when ready
223	                ch.config().setOption(Http2StreamChannelOption.AUTO_STREAM_FLOW_CONTROL, false);
224	                ChannelPipeline p = ch.pipeline();
225	                p.addLast(new NettyHttp2FrameCodec(nettyHttp2SettingsHandler));
226	                p.addLast(new NettyHttp2ProtocolSelectorHandler(
227	                        url,
228	                        frameworkModel,
229	                        tripleConfig,
230	                        GenericHttp2ServerTransportListenerFactory.INSTANCE,
231	                        http2Connection));
232	            }
233	        });
234	    }
