30	
31	/**
32	 * Execute exactly once, which means this policy will throw an exception immediately in case of an invocation error.
33	 * Usually used for non-idempotent write operations
34	 *
35	 * <a href="http://en.wikipedia.org/wiki/Fail-fast">Fail-fast</a>
36	 */
37	public class FailfastClusterInvoker<T> extends AbstractClusterInvoker<T> {
38	
39	    public FailfastClusterInvoker(Directory<T> directory) {
40	        super(directory);
41	    }
42	
43	    @Override
44	    public Result doInvoke(Invocation invocation, List<Invoker<T>> invokers, LoadBalance loadbalance)
45	            throws RpcException {
46	        Invoker<T> invoker = select(loadbalance, invocation, invokers, null);
47	        try {
48	            return invokeWithContext(invoker, invocation);
49	        } catch (Throwable e) {
50	            if (e instanceof RpcException && ((RpcException) e).isBiz()) { // biz exception.
51	                throw (RpcException) e;
52	            }
53	            throw new RpcException(
54	                    e instanceof RpcException ? ((RpcException) e).getCode() : 0,
55	                    "Failfast invoke providers " + invoker.getUrl() + " "
56	                            + loadbalance.getClass().getSimpleName()
57	                            + " for service " + getInterface().getName()
58	                            + " method " + RpcUtils.getMethodName(invocation) + " on consumer "
59	                            + NetUtils.getLocalHost()
60	                            + " use dubbo version " + Version.getVersion()
61	                            + ", but no luck to perform the invocation. Last error is: " + e.getMessage(),
62	                    e.getCause() != null ? e.getCause() : e);
63	        }
64	    }
65	}
