17	package org.apache.dubbo.remoting.api.connection;
18	
19	import org.apache.dubbo.common.URL;
20	import org.apache.dubbo.common.logger.ErrorTypeAwareLogger;
21	import org.apache.dubbo.common.logger.LoggerFactory;
22	import org.apache.dubbo.remoting.ChannelHandler;
23	import org.apache.dubbo.remoting.Constants;
24	import org.apache.dubbo.rpc.model.FrameworkModel;
25	
26	import java.util.concurrent.ConcurrentHashMap;
27	import java.util.concurrent.ConcurrentMap;
28	import java.util.function.Consumer;
29	
30	public class SingleProtocolConnectionManager implements ConnectionManager {
31	    private static final ErrorTypeAwareLogger logger =
32	            LoggerFactory.getErrorTypeAwareLogger(SingleProtocolConnectionManager.class);
33	
34	    public static final String NAME = "single";
35	
36	    private final ConcurrentMap<String, AbstractConnectionClient> connections = new ConcurrentHashMap<>(16);
37	
38	    private FrameworkModel frameworkModel;
39	
40	    public SingleProtocolConnectionManager(FrameworkModel frameworkModel) {
41	        this.frameworkModel = frameworkModel;
42	    }
43	
44	    @Override
45	    public AbstractConnectionClient connect(URL url, ChannelHandler handler) {
46	        if (url == null) {
47	            throw new IllegalArgumentException("url == null");
48	        }
49	        return connections.compute(url.getAddress(), (address, conn) -> {
50	            String transport = url.getParameter(Constants.TRANSPORTER_KEY, "netty4");
51	            if (conn == null) {
52	                return createAbstractConnectionClient(url, handler, address, transport);
53	            } else {
54	                boolean shouldReuse = conn.retain();
55	                if (!shouldReuse) {
56	                    logger.info("Trying to create a new connection for {}.", address);
57	                    return createAbstractConnectionClient(url, handler, address, transport);
58	                }
59	                return conn;
60	            }
61	        });
62	    }
63	
64	    private AbstractConnectionClient createAbstractConnectionClient(
65	            URL url, ChannelHandler handler, String address, String transport) {
66	        ConnectionManager manager =
67	                frameworkModel.getExtensionLoader(ConnectionManager.class).getExtension(transport);
68	        final AbstractConnectionClient connectionClient = manager.connect(url, handler);
69	        connectionClient.addCloseListener(() -> {
70	            logger.info(
71	                    "Remove closed connection (with reference count==0) for address {}, a new one will be created for upcoming RPC requests routing to this address.",
72	                    address);
73	            connections.remove(address, connectionClient);
74	        });
75	        return connectionClient;
76	    }
77	
78	    @Override
79	    public void forEachConnection(Consumer<AbstractConnectionClient> connectionConsumer) {
80	        connections.values().forEach(connectionConsumer);
81	    }
82	}
