184	    class CallbackRegistrationInvoker<T, FILTER extends BaseFilter> implements Invoker<T> {
185	        private static final ErrorTypeAwareLogger LOGGER =
186	                LoggerFactory.getErrorTypeAwareLogger(CallbackRegistrationInvoker.class);
187	        final Invoker<T> filterInvoker;
188	        final List<FILTER> filters;
