193	        }
194	
195	        @Override
196	        public Result invoke(Invocation invocation) throws RpcException {
197	            Result asyncResult = filterInvoker.invoke(invocation);
198	            asyncResult.whenCompleteWithContext((r, t) -> {
199	                RuntimeException filterRuntimeException = null;
200	                for (int i = filters.size() - 1; i >= 0; i--) {
201	                    FILTER filter = filters.get(i);
202	                    try {
203	                        InvocationProfilerUtils.releaseDetailProfiler(invocation);
204	                        if (filter instanceof ListenableFilter) {
205	                            ListenableFilter listenableFilter = ((ListenableFilter) filter);
206	                            Filter.Listener listener = listenableFilter.listener(invocation);
207	                            try {
208	                                if (listener != null) {
209	                                    if (t == null) {
210	                                        listener.onResponse(r, filterInvoker, invocation);
211	                                    } else {
212	                                        listener.onError(t, filterInvoker, invocation);
213	                                    }
214	                                }
215	                            } finally {
216	                                listenableFilter.removeListener(invocation);
217	                            }
218	                        } else if (filter instanceof FILTER.Listener) {
219	                            FILTER.Listener listener = (FILTER.Listener) filter;
220	                            if (t == null) {
221	                                listener.onResponse(r, filterInvoker, invocation);
222	                            } else {
223	                                listener.onError(t, filterInvoker, invocation);
224	                            }
225	                        }
226	                    } catch (RuntimeException runtimeException) {
227	                        LOGGER.error(
228	                                CLUSTER_EXECUTE_FILTER_EXCEPTION,
229	                                "the custom filter is abnormal",
230	                                "",
231	                                String.format(
232	                                        "Exception occurred while executing the %s filter named %s.",
233	                                        i, filter.getClass().getSimpleName()));
234	                        if (LOGGER.isDebugEnabled()) {
235	                            LOGGER.debug(String.format(
236	                                    "Whole filter list is: %s",
237	                                    filters.stream()
238	                                            .map(tmpFilter ->
239	                                                    tmpFilter.getClass().getSimpleName())
240	                                            .collect(Collectors.toList())));
241	                        }
242	                        filterRuntimeException = runtimeException;
243	                        t = runtimeException;
244	                    }
245	                }
246	                if (filterRuntimeException != null) {
247	                    throw filterRuntimeException;
248	                }
249	            });
250	
251	            return asyncResult;
252	        }
